window.RPG_GYM_EXERCISES = [{"id":"Plank","name":"Prancha","force":"static","level":"iniciante","mechanic":"isolado","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Fique em posição prona, apoiado nos dedos dos pés e antebraços, com os braços alinhados aos ombros.","Mantenha o corpo reto pelo maior tempo possível. Para aumentar a dificuldade, levante um braço ou perna."],"tracking":"time"},{"id":"3_4_Sit-Up","name":"Abdominal 3/4","force":"pull","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se no chão e prenda os pés. As pernas devem estar flexionadas nos joelhos.","Coloque as mãos atrás ou ao lado da cabeça. Comece com as costas no chão. Esta é a posição inicial.","Flexione os quadris e a coluna para levantar o tronco em direção aos joelhos.","No topo da contração, o tronco deve estar perpendicular ao chão. Inverta o movimento, descendo apenas 3/4 do caminho."],"tracking":"reps"},{"id":"Side_Bridge","name":"Prancha Lateral","force":"static","level":"iniciante","mechanic":null,"equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":["ombros"],"category":"forca","instructions":[],"tracking":"time"},{"id":"Leg_Pull-In","name":"Puxada de Pernas","force":"pull","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se em um colchonete com as pernas estendidas e as mãos apoiadas ao lado do corpo ou sob os glúteos. Esta é a posição inicial.","Dobre os joelhos e puxe as coxas em direção ao abdômen enquanto expira, contraindo os abdominais. Mantenha os joelhos próximos ao peito por um segundo.","Volte à posição inicial enquanto inspira.","Repita para a quantidade recomendada de repetições."],"tracking":"reps"},{"id":"Cross-Body_Crunch","name":"Abdominal Cruzado","force":"pull","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se de costas com os joelhos flexionados a cerca de 60 graus.","Mantenha os pés apoiados no chão e as mãos soltas atrás da cabeça. Esta é a posição inicial.","Flexione o tronco e traga o cotovelo e ombro direito em direção ao joelho esquerdo, que deve se aproximar do ombro. Tente tocar o joelho com o cotovelo, expirando e contraindo o abdômen.","Volte à posição inicial inspirando e repita com o cotovelo esquerdo e joelho direito."],"tracking":"reps"},{"id":"Reverse_Crunch","name":"Abdominal Inverso","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se no chão com as pernas estendidas e os braços ao lado do torso, palmas no chão. Os braços devem ficar imóveis.","Levante as pernas até as coxas ficarem perpendiculares ao chão e os pés juntos e paralelos ao chão. Esta é a posição inicial.","Ao inspirar, aproxime as pernas do torso, rolando a pélvis para trás e elevando os quadris do chão. No final, os joelhos devem tocar o peito.","Segure a contração por um segundo e retorne as pernas à posição inicial enquanto expira."],"tracking":"reps"},{"id":"Tuck_Crunch","name":"Abdominal Agrupado","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se de costas no chão ou em um colchonete, com os braços ao lado do corpo e as palmas para baixo.","Cruze as pernas, envolvendo um tornozelo no outro, e eleve as pernas até as coxas ficarem perpendiculares ao chão, com os joelhos levemente flexionados. Os joelhos e pés devem ficar paralelos ao chão.","Mova os braços do chão e cruze-os sobre o peito. Esta é a posição inicial.","Mantendo a parte inferior das costas pressionada contra o chão, levante o tronco lentamente, expirando."],"tracking":"reps"},{"id":"Jackknife_Sit-Up","name":"Abdominal Canivete","force":"pull","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se de costas no chão com os braços estendidos para trás da cabeça e as pernas estendidas. Esta é a posição inicial.","Expire e flexione o tronco, levantando simultaneamente as pernas e os braços para se encontrar em posição de canivete. As pernas devem estar elevadas a 35-45 graus do chão, e os braços paralelos a elas, com o torso fora do chão.","Inspire e retorne os braços e pernas à posição inicial.","Repita pelo número recomendado de repetições."],"tracking":"reps"},{"id":"Cable_Crunch","name":"Abdominal na Polia","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Ajoelhe-se abaixo de uma polia alta com uma corda presa.","Segure a corda e abaixe-a até as mãos ficarem próximas ao rosto.","Flexione levemente os quadris para alongar a lombar. Esta é a posição inicial.","Com os quadris parados, flexione a cintura contraindo o abdômen até os cotovelos se aproximarem das coxas, expirando e segurando a contração por um segundo."],"tracking":"weight_reps"},{"id":"Decline_Crunch","name":"Abdominal Declinado","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Prenda as pernas na extremidade do banco declinado e deite-se.","Coloque as mãos levemente ao lado da cabeça, com os cotovelos para dentro. Dica: Não entrelace os dedos atrás da cabeça.","Mantenha a região lombar pressionada no banco para isolar os abdominais e comece a levantar os ombros.","Continue pressionando a lombar enquanto contrai os abdominais e expira. Os ombros devem subir apenas cerca de 10 cm, e a lombar deve permanecer no banco. No topo, contraia os abdominais por um segundo. Dica: Faça movimentos lentos e controlados, sem usar impulso."],"tracking":"reps"},{"id":"Ab_Crunch_Machine","name":"Máquina de Abdominal","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"maquina","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Selecione uma resistência leve e sente-se na máquina, colocando os pés sob as almofadas e segurando as alças superiores. Os braços devem estar flexionados a 90 graus, com os tríceps apoiados nas almofadas. Esta é a posição inicial.","Ao mesmo tempo, comece a levantar as pernas enquanto faz um crunch com o tronco superior. Expire ao realizar este movimento. Dica: Use um movimento lento e controlado, concentrando-se nos abdominais.","Após uma pausa de um segundo, retorne lentamente à posição inicial enquanto inspira.","Repita o movimento para a quantidade prescrita de repetições."],"tracking":"weight_reps"},{"id":"Cable_Reverse_Crunch","name":"Abdominal Infra na Polia","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Conecte uma tornozeira à polia baixa e coloque um colchonete no chão à frente.","Sente-se com os pés voltados para a polia e prenda o cabo aos tornozelos.","Deite-se, eleve as pernas e flexione os joelhos em um ângulo de 90 graus. As pernas e o cabo devem estar alinhados; ajuste a polia se necessário.","Com as mãos atrás da cabeça, aproxime os joelhos do torso e eleve os quadris do chão."],"tracking":"weight_reps"},{"id":"Cable_Seated_Crunch","name":"Abdominal Sentado na Polia","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se em um banco plano de costas para uma polia alta.","Segure a corda da polia com as duas mãos (palmas viradas uma para a outra) e posicione as mãos sobre os ombros. Dica: Permita uma leve hiperextensão lombar. Esta é a posição inicial.","Com os quadris imóveis, flexione a cintura trazendo os cotovelos em direção aos quadris. Expire durante o movimento.","Inspire ao retornar lentamente à posição inicial."],"tracking":"weight_reps"},{"id":"Seated_Flat_Bench_Leg_Pull-In","name":"Abdominal no Banco Sentado","force":"pull","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se em um banco com as pernas estendidas à frente, ligeiramente abaixo do paralelo, e os braços segurando as laterais do banco. O torso deve estar inclinado para trás em um ângulo de cerca de 45 graus. Esta será a posição inicial.","Aproxime os joelhos em sua direção enquanto move o torso em direção a eles ao mesmo tempo. Expire ao realizar este movimento.","Após uma pausa de um segundo, retorne à posição inicial enquanto inspira.","Repita para a quantidade recomendada de repetições."],"tracking":"reps"},{"id":"Crunch_-_Legs_On_Exercise_Ball","name":"Abdominal com Pernas na Bola","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se de costas com os pés apoiados em uma bola de exercício e joelhos flexionados a 90 graus.","Mantenha os pés levemente afastados e dedos apontados para dentro, tocando-se.","Coloque as mãos levemente ao lado da cabeça, cotovelos para dentro.","Pressione a região lombar no chão para isolar o abdômen. Esta é a posição inicial."],"tracking":"reps"},{"id":"Side_Jackknife","name":"Abdominal Lateral (Jackknife)","force":"pull","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":[],"tracking":"reps"},{"id":"Rope_Crunch","name":"Abdominal com Corda no Pulley","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Ajoelhe-se a 30-60 cm de um sistema de cabo com uma corda presa.","Segure a corda com as duas mãos acima da cabeça, com o tronco ereto.","Flexione a coluna, tentando aproximar as costelas das pernas enquanto puxa a corda para baixo.","Segure na parte inferior do movimento e retorne lentamente à posição inicial."],"tracking":"weight_reps"},{"id":"Flat_Bench_Leg_Pull-In","name":"Puxada de Joelho no Banco Plano","force":"pull","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se em um banco plano ou colchonete com as pernas estendidas para fora.","Coloque as mãos sob os glúteos ou ao lado do corpo segurando o banco. Esta é a posição inicial.","Dobre os joelhos e puxe as coxas em direção ao tronco, expirando. Segure a contração por um segundo.","Inspire e retorne lentamente à posição inicial."],"tracking":"reps"},{"id":"Crunch_-_Hands_Overhead","name":"Abdominal com Mãos Acima da Cabeça","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se de costas com os joelhos flexionados a cerca de 60 graus.","Mantenha os pés no chão e estique os braços acima da cabeça com as palmas cruzadas. Esta é a posição inicial.","Flexione o tronco para frente, levantando as escápulas do chão. Mantenha os braços alinhados com a cabeça, pescoço e ombros, expirando. Segure a contração por um segundo.","Volte lentamente à posição inicial inspirando."],"tracking":"reps"},{"id":"Seated_Leg_Tucks","name":"Abdominal Sentado com Flexão de Joelhos","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"peso-do-corpo","primaryMuscles":["abdominais"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se em um banco com as pernas estendidas ligeiramente abaixo do paralelo e as mãos segurando as laterais do banco. Incline o tronco para trás em um ângulo de 45 graus. Esta é a posição inicial.","Aproxime os joelhos de você enquanto move o tronco em direção a eles, expirando.","Após uma pausa de um segundo, retorne à posição inicial, inspirando.","Repita para as repetições recomendadas."],"tracking":"reps"},{"id":"Barbell_Ab_Rollout","name":"Abdominal com Roda de Abdominais usando Barra","force":"pull","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["abdominais"],"secondaryMuscles":["inferior-das-costas","ombros"],"category":"forca","instructions":["Posicione-se em uma posição de flexão, mas em vez de apoiar as mãos no chão, segure uma barra olímpica (com 2 a 5 kg de cada lado). Esta será sua posição inicial.","Mantendo uma leve curvatura nas costas, levante os quadris e role a barra em direção aos pés enquanto expira. Mantenha os abdominais contraídos e os braços perpendiculares ao chão.","Após uma breve contração no topo, role a barra de volta lentamente à posição inicial enquanto inspira.","Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Drag_Curl","name":"Rosca Drag","force":"pull","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Segure uma barra com pegada supinada (palmas para frente), cotovelos próximos ao tronco e levemente para trás. Esta é a posição inicial.","Expire e flexione os braços, arrastando a barra para cima em contato com o torso, mantendo os cotovelos para trás e os ombros baixos.","Volte lentamente à posição inicial, mantendo a barra em contato com o torso.","Repita para a quantidade recomendada de repetições."],"tracking":"weight_reps"},{"id":"Hammer_Curls","name":"Rosca Martelo","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Fique em pé com o torso ereto e um halter em cada mão, mantidos ao longo do corpo. Os cotovelos devem ficar próximos ao torso.","As palmas das mãos devem estar voltadas para o torso. Esta será sua posição inicial.","Mantendo o braço superior parado, expire e curve o peso para cima, contraindo o bíceps. Continue levantando até que o bíceps esteja totalmente contraído e o halter esteja na altura do ombro. Segure a posição contraída por um momento, apertando o bíceps. Dica: Foque em manter o cotovelo parado e movimentar apenas o antebraço.","Após a pausa, inspire e comece a abaixar os halteres lentamente de volta à posição inicial."],"tracking":"weight_reps"},{"id":"Concentration_Curls","name":"Rosca Concentrada","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Sente-se em um banco plano com um halter entre as pernas. As pernas devem estar afastadas, joelhos flexionados e pés no chão.","Com o braço direito, segure o halter. Apoie a parte de trás do braço direito na parte interna da coxa direita, com a palma da mão voltada para frente. O braço deve estar estendido e o halter acima do chão. Esta é a posição inicial.","Mantendo o braço superior parado, flexione o halter contraindo o bíceps enquanto expira. Apenas o antebraço deve se mover. Continue até o bíceps estar totalmente contraído e o halter na altura do ombro. Na parte alta, o dedo mínimo deve estar acima do polegar para uma boa contração. Segure a contração por um segundo.","Volte lentamente à posição inicial enquanto inspira. Evite balançar."],"tracking":"weight_reps"},{"id":"EZ-Bar_Curl","name":"Rosca com Barra W","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"barra-w","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Fique em pé segurando uma barra W nas alças externas mais largas, com as palmas das mãos voltadas para frente e ligeiramente inclinadas para dentro devido ao formato da barra. Mantenha os cotovelos próximos ao torso. Esta será sua posição inicial.","Mantendo a parte superior dos braços parada, expire e faça a rosca para frente contraindo o bíceps, movendo apenas os antebraços.","Continue levantando o peso até o bíceps estar totalmente contraído e a barra estiver na altura dos ombros. Segure a posição contraída por um momento e aperte o bíceps.","Então, inspire e abaixe lentamente a barra de volta à posição inicial."],"tracking":"weight_reps"},{"id":"Standing_Inner-Biceps_Curl","name":"Rosca Martelo em Pé","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Fique em pé com um halter em cada mão ao lado do corpo, pés na largura dos ombros e palmas voltadas para dentro.","Mantendo os braços superiores imóveis, flexione os halteres para cima, girando os pulsos até as palmas ficarem voltadas para cima.","Contraia os bíceps totalmente e segure por um segundo.","Abaixe os halteres lentamente, girando os pulsos de volta à posição neutra."],"tracking":"weight_reps"},{"id":"Machine_Preacher_Curls","name":"Rosca Scott Máquina","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se na Máquina de Rosca Scott e selecione o peso.","Apoie a parte posterior dos braços superiores (tríceps) na almofada e segure as alças com pegada supinada (palmas para cima). Dica: Mantenha os cotovelos para dentro. Esta será sua posição inicial.","Levante as alças, expirando e contraindo os bíceps. Segure a contração por um segundo no topo. Dica: Apenas os antebraços devem se mover; braços superiores estacionários na almofada.","Abaixe as alças lentamente à posição inicial, inspirando."],"tracking":"weight_reps"},{"id":"Machine_Bicep_Curl","name":"Rosca Direta Máquina","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Ajuste o banco à altura adequada e selecione o peso. Apoie os braços superiores nas almofadas e segure as alças. Esta será sua posição inicial.","Flexione os cotovelos, puxando os antebraços em direção aos braços superiores.","Faça uma pausa no topo do movimento e retorne lentamente o peso à posição inicial.","Evite retornar o peso completamente até o final do conjunto para manter a tensão nos músculos."],"tracking":"weight_reps"},{"id":"Cable_Preacher_Curl","name":"Rosca Scott na Polia","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Posicione um banco Scott a cerca de 60 cm na frente de uma máquina de polia.","Conecte uma barra reta à polia baixa.","Sente-se no banco Scott, apoiando firmemente os cotovelos e a parte superior dos braços na almofada, e peça para alguém entregar a barra da polia.","Segure a barra com os braços totalmente estendidos sobre a almofada. Esta é a posição inicial."],"tracking":"weight_reps"},{"id":"Reverse_Cable_Curl","name":"Rosca Inversa no Cabo","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Fique em pé com o tronco ereto, segurando uma barra presa a uma polia baixa, com pegada pronada na largura dos ombros e cotovelos próximos ao corpo. Esta é a posição inicial.","Mantendo a parte superior dos braços parada, flexione os pesos contraindo o bíceps enquanto expira. Apenas os antebraços devem se mover. Continue até o bíceps estar totalmente contraído e a barra na altura dos ombros. Segure a contração por um segundo.","Volte lentamente à posição inicial enquanto inspira.","Repita para as repetições recomendadas."],"tracking":"weight_reps"},{"id":"Cross_Body_Hammer_Curl","name":"Rosca Martelo Cruzada","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Fique em pé com um halter em cada mão, braços estendidos ao lado do corpo e palmas voltadas para dentro.","Com as palmas ainda voltadas para dentro, flexione o halter direito em direção ao ombro esquerdo enquanto expira, sem torcer o braço. Toque o halter no ombro e segure a contração por um segundo.","Volte lentamente à posição inicial inspirando e repita com o braço esquerdo.","Continue alternando até completar as repetições para cada braço."],"tracking":"weight_reps"},{"id":"High_Cable_Curls","name":"Rosca com Cabos Altos","force":"pull","level":"intermediario","mechanic":"composto","equipment":"cabo","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Fique entre duas polias altas e segure uma alça em cada mão. Posicione os braços superiores paralelos ao chão, com as palmas voltadas para você. Esta é a posição inicial.","Flexione os braços trazendo as alças em direção às orelhas, contraindo os bíceps e expirando. Mantenha os braços superiores imóveis, movendo apenas os antebraços. Segure por um segundo na posição contraída.","Retorne lentamente os braços à posição inicial.","Repita para o número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Barbell_Curl","name":"Rosca Direta com Barra","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Fique em pé com o tronco ereto, segurando uma barra com pegada na largura dos ombros. As palmas devem estar voltadas para frente e os cotovelos próximos ao corpo. Esta será sua posição inicial.","Mantendo os braços superiores parados, curve os pesos para frente contraindo o bíceps enquanto expira. Apenas os antebraços devem se mover.","Continue até o bíceps estar totalmente contraído e a barra na altura dos ombros. Segure a contração por um segundo e aperte o bíceps.","Volte lentamente à posição inicial enquanto inspira."],"tracking":"weight_reps"},{"id":"Lying_Cable_Curl","name":"Rosca com Cabo Deitado","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"cabo","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Segure uma barra reta ou barra W presa à polia baixa com as duas mãos, usando uma pegada supinada (palmas para cima) na largura dos ombros.","Deite-se de costas em um colchonete em frente à pilha de pesos, com os pés apoiados na estrutura da máquina e as pernas estendidas.","Com os braços estendidos e os cotovelos próximos ao corpo, dobre levemente os braços. Esta será a posição inicial.","Mantendo a parte superior dos braços parada e os cotovelos próximos ao corpo, curve a barra lentamente em direção ao peito enquanto expira e contrai o bíceps."],"tracking":"weight_reps"},{"id":"Standing_Concentration_Curl","name":"Rosca Concentrada em Pé","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Segure um halter com a mão de trabalho e incline-se para frente. Deixe o braço pendendo perpendicular ao chão, com o cotovelo apontando para fora. Esta é a posição inicial.","Dobre o cotovelo para levantar o peso, mantendo a parte superior do braço imóvel. No topo, contraia o bíceps e faça uma pausa.","Abaixe o halter de volta à posição inicial.","Repita o movimento pelo número de repetições prescrito."],"tracking":"weight_reps"},{"id":"Reverse_Barbell_Curl","name":"Rosca Inversa com Barra","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Fique em pé com o tronco ereto, segurando uma barra na largura dos ombros, com os cotovelos próximos ao corpo e as palmas voltadas para baixo (pegada pronada). Esta é a posição inicial.","Mantendo a parte superior dos braços parada, flexione os pesos contraindo o bíceps enquanto expira. Apenas os antebraços devem se mover. Continue até o bíceps estar totalmente contraído e a barra na altura dos ombros. Segure a contração por um segundo.","Volte lentamente à posição inicial enquanto inspira.","Repita para as repetições recomendadas."],"tracking":"weight_reps"},{"id":"Incline_Hammer_Curls","name":"Rosca Martelo Inclinada","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se em um banco inclinado com um haltere em cada mão, costas firmes contra o encosto e pés juntos. Deixe os halteres pendurados ao lado do corpo com pegada neutra (palmas voltadas uma para a outra). Esta é a posição inicial.","Flexione os cotovelos, mantendo a parte superior dos braços parada.","Continue até o topo do movimento, pause e retorne lentamente à posição inicial."],"tracking":"weight_reps"},{"id":"Dumbbell_Bicep_Curl","name":"Rosca Bíceps com Halteres","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Fique em pé, ereto, com um halter em cada mão e os braços estendidos. Mantenha os cotovelos próximos ao tronco e gire as palmas das mãos até ficarem voltadas para frente. Esta será a posição inicial.","Mantendo a parte superior dos braços parada, expire e faça a rosca dos pesos enquanto contrai os bíceps. Continue levantando até que os bíceps estejam totalmente contraídos e os halteres na altura dos ombros. Segure a posição contraída por um breve instante, apertando os bíceps.","Em seguida, inspire e comece a baixar os halteres lentamente de volta à posição inicial.","Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Incline_Dumbbell_Curl","name":"Rosca Inclinada com Halteres","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se em um banco inclinado com um haltere em cada mão, mantendo os braços estendidos ao lado do corpo. Mantenha os cotovelos próximos ao tronco e gire os punhos até as palmas das mãos ficarem voltadas para a frente. Esta é a posição inicial.","Mantendo a parte superior dos braços parada, flexione os cotovelos e levante os halteres contraindo o bíceps enquanto expira. Apenas os antebraços devem se mover. Continue até o bíceps estar totalmente contraído e os halteres na altura dos ombros. Segure a posição contraída por um segundo.","Volte lentamente à posição inicial enquanto inspira.","Repita para a quantidade recomendada de repetições."],"tracking":"weight_reps"},{"id":"Preacher_Hammer_Dumbbell_Curl","name":"Rosca Martelo no Banco Scott","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Apoie a parte superior dos braços no banco Scott, segurando um halter em cada mão com as palmas voltadas uma para a outra (pegada neutra).","Inspire e abaixe os halteres lentamente até o braço ficar estendido e o bíceps alongado.","Exale e use o bíceps para levantar o peso até a contração total, halteres na altura dos ombros.","Mantenha a contração por um segundo e repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Reverse_Barbell_Preacher_Curls","name":"Rosca Scott Inversa com Barra","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"barra-w","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Segure uma barra W na largura dos ombros com as palmas voltadas para baixo (pegada pronada).","Apoie a parte superior dos braços no banco Scott, com os braços estendidos. Esta é a posição inicial.","Ao expirar, use o bíceps para flexionar o peso até a contração total, com a barra na altura dos ombros. Contraia o bíceps firmemente por um segundo.","Ao inspirar, abaixe lentamente a barra até os braços estarem estendidos e o bíceps alongado."],"tracking":"weight_reps"},{"id":"Lying_High_Bench_Barbell_Curl","name":"Rosca Scott com Barra Deitado","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"barra","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se de bruços em um banco alto segurando uma barra com pegada supinada (palmas para cima). Dica: Se usar uma barra reta, segure-a com uma pegada na largura dos ombros; se usar uma barra W, segure nas alças internas. Posicione o torso de modo que o peito superior fique sobre a extremidade do banco e a barra pendurada à sua frente, com os braços estendidos e perpendiculares ao chão. Esta será sua posição inicial.","Mantendo os cotovelos fixos e a parte superior dos braços estacionária, curve o peso para cima em um movimento semicircular enquanto contrai o bíceps e expira. Segure no topo do movimento por um segundo.","Ao inspirar, retorne lentamente à posição inicial. Dica: Mantenha controle total do peso e evite balanços. Apenas os antebraços devem se mover.","Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Seated_Dumbbell_Curl","name":"Rosca Scott com Halter Sentado","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se em um banco reto com um halter em cada mão, mantendo os braços estendidos. Os cotovelos devem ficar próximos ao torso.","Gire as palmas das mãos para que fiquem voltadas para o torso. Esta será a posição inicial.","Mantendo a parte superior dos braços parada, flexione os pesos e comece a girar os pulsos quando os halteres passarem pelas coxas, de modo que as palmas fiquem voltadas para a frente no final do movimento. Contraia o bíceps ao expirar e certifique-se de que apenas os antebraços se movam. Continue até que o bíceps esteja totalmente contraído e os halteres estejam na altura dos ombros. Segure a posição contraída por um segundo, apertando o bíceps.","Volte lentamente à posição inicial enquanto inspira e gira os pulsos de volta para uma pegada neutra."],"tracking":"weight_reps"},{"id":"Standing_Dumbbell_Reverse_Curl","name":"Rosca Inversa com Halteres em Pé","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Fique em pé, segurando um halter em cada mão com pegada pronada (palmas para baixo). Braços totalmente estendidos e pés na largura dos ombros. Esta é a posição inicial.","Mantendo a parte superior dos braços imóvel, curve os pesos contraindo o bíceps ao expirar. Apenas os antebraços devem se mover. Continue até o bíceps estar totalmente contraído e os halteres na altura dos ombros. Segure a contração por um segundo.","Volte lentamente à posição inicial ao inspirar.","Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Seated_Dumbbell_Inner_Biceps_Curl","name":"Rosca Martelo com Halter Sentado","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se na ponta de um banco reto com um halter em cada mão, mantendo os braços estendidos. Os cotovelos devem ficar próximos ao torso.","Gire as palmas das mãos para que fiquem voltadas para dentro, em uma posição neutra. Esta será a posição inicial.","Mantendo a parte superior dos braços parada, flexione os halteres para fora e para cima, girando as palmas para fora durante o levantamento e mantendo os antebraços alinhados com os deltoides externos. Dica:","Apenas os antebraços devem se mover. Continue até que o bíceps esteja totalmente contraído e os halteres estejam na altura dos ombros. Segure a posição contraída por um segundo, apertando o bíceps."],"tracking":"weight_reps"},{"id":"Cable_Hammer_Curls_-_Rope_Attachment","name":"Rosca Martelo na Polia com Corda","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Prenda uma corda na polia baixa e fique de frente para a máquina, a cerca de 30 cm de distância.","Segure a corda com pegada neutra (palmas voltadas uma para a outra) e mantenha a postura ereta.","Mantenha os cotovelos junto ao corpo, fixos. Esta é a posição inicial.","Puxe os braços com os bíceps até tocarem os antebraços, expirando."],"tracking":"weight_reps"},{"id":"Barbell_Curls_Lying_Against_An_Incline","name":"Rosca com Barra no Banco Inclinado","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se em um banco inclinado, com os braços segurando uma barra e pendurados em linha horizontal. Esta será sua posição inicial.","Mantendo os braços superiores parados, curve o peso o mais alto possível enquanto contrai o bíceps, expirando. Apenas os antebraços devem se mover.","Após uma contração, volte lentamente à posição inicial enquanto inspira, certificando-se de descer completamente.","Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Incline_Inner_Biceps_Curl","name":"Rosca Inclinada para Bíceps Interno","force":null,"level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Segure um haltere em cada mão e deite-se em um banco inclinado.","Os halteres devem estar estendidos ao lado do corpo com as palmas voltadas para fora. Esta é a posição inicial.","Expire e curve os pesos para fora e para cima, mantendo os antebraços alinhados com os deltoides laterais. Continue até os halteres estarem na altura dos ombros e ao lado dos deltoides, como na pose de bíceps duplo.","Após uma contração no topo, inspire e abaixe os pesos lentamente pelo mesmo caminho."],"tracking":"weight_reps"},{"id":"Close-Grip_EZ_Bar_Curl","name":"Rosca com Barra W em Pegada Fechada","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Fique em pé com o torso ereto, segurando uma barra W na pegada interna mais próxima. As palmas das mãos devem estar voltadas para a frente e ligeiramente inclinadas para dentro devido ao formato da barra. Os cotovelos devem ficar próximos ao torso. Esta será sua posição inicial.","Mantendo a parte superior dos braços parada, curve os pesos para a frente enquanto contrai os bíceps e expira. Dica: Apenas os antebraços devem se mover.","Continue o movimento até os bíceps estarem totalmente contraídos e a barra estiver na altura dos ombros. Segure a posição contraída por um segundo e contraia os bíceps com força.","Lentamente, comece a trazer a barra de volta à posição inicial enquanto inspira."],"tracking":"weight_reps"},{"id":"Dumbbell_Prone_Incline_Curl","name":"Rosca Inclinada com Halteres Deitado","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Segure um halter em cada mão e deite-se de bruços em um banco inclinado, com os ombros próximos ao topo. Os joelhos podem apoiar no banco ou as pernas ficar abertas.","Deixe os braços estendidos e pendurados naturalmente à frente, perpendiculares ao chão.","Mantenha os cotovelos junto ao corpo e as palmas das mãos voltadas para frente. Esta é a posição inicial.","Expire e contraia o bíceps para levantar os halteres até os braços ficarem totalmente flexionados, movendo apenas os antebraços."],"tracking":"weight_reps"},{"id":"Standing_Biceps_Cable_Curl","name":"Rosca Direta com Barra na Polia em Pé","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Fique em pé com o tronco ereto, segurando uma barra de rosca presa a uma polia baixa. Segure a barra na largura dos ombros e mantenha os cotovelos próximos ao torso, com as palmas viradas para cima (pegada supinada). Esta é a posição inicial.","Mantendo os braços superiores parados, flexione os pesos contraindo o bíceps enquanto expira. Apenas os antebraços devem se mover. Continue até que o bíceps esteja totalmente contraído e a barra esteja na altura dos ombros. Segure a contração por um segundo, apertando o músculo.","Comece a retornar a barra lentamente à posição inicial, inspirando.","Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Wide-Grip_Standing_Barbell_Curl","name":"Rosca Direta com Barra em Pegada Aberta","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Fique em pé com o tronco ereto, segurando uma barra com as mãos na pegada aberta. As palmas devem estar voltadas para frente e os cotovelos próximos ao corpo. Esta é a posição inicial.","Mantendo a parte superior dos braços parada, flexione os pesos para frente contraindo o bíceps enquanto expira. Dica: Apenas os antebraços devem se mover.","Continue o movimento até o bíceps estar totalmente contraído e a barra na altura dos ombros. Segure a posição contraída por um segundo e aperte o bíceps com força.","Lentamente, retorne a barra à posição inicial enquanto inspira."],"tracking":"weight_reps"},{"id":"Close-Grip_Standing_Barbell_Curl","name":"Rosca com Barra em Pé em Pegada Fechada","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["biceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Segure uma barra com as duas mãos, palmas para cima e a alguns centímetros de distância.","Fique em pé com o torso reto e a cabeça erguida. Os pés devem estar na largura dos ombros e os cotovelos próximos ao torso. Esta será sua posição inicial. Dica: Mantenha a parte superior dos braços e os cotovelos parados durante todo o movimento.","Curve a barra para cima em um movimento semicircular até os antebraços tocarem os bíceps. Expire ao executar esta parte e contraia os bíceps com força por um segundo no topo. Dica: Evite curvar as costas ou usar balanço; apenas os antebraços devem se mover.","Volte lentamente à posição inicial enquanto inspira."],"tracking":"weight_reps"},{"id":"Flexor_Incline_Dumbbell_Curls","name":"Rosca Scott com Halteres no Banco Inclinado","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se em um banco inclinado a 45 graus segurando um halter em cada mão, com os braços estendidos ao lado do corpo e as palmas voltadas para frente.","Mantenha os pulsos neutros para evitar estresse. Esta é a posição inicial.","Faça a rosca simultaneamente com os dois halteres até a contração total do bíceps, expirando. Segure a contração por um segundo no topo.","Inspire e retorne lentamente à posição inicial."],"tracking":"weight_reps"},{"id":"Seated_Close-Grip_Concentration_Barbell_Curl","name":"Rosca Concentrada com Barra em Pegada Fechada Sentado","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"barra","primaryMuscles":["biceps"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se em um banco plano com uma barra entre as pernas. As pernas devem estar abertas, com joelhos flexionados e pés no chão.","Pegue a barra e apoie a parte de trás dos braços nas coxas (cerca de 9 cm dos joelhos). Use uma pegada supinada mais fechada que a largura dos ombros. O braço deve estar estendido e a barra acima do chão. Esta é a posição inicial.","Mantenha os braços imóveis e curve a barra para frente, contraindo o bíceps. Expire. Apenas os antebraços se movem.","Contraia totalmente o bíceps e segure por um segundo."],"tracking":"weight_reps"},{"id":"Chin-Up","name":"Chin-Up","force":"pull","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["dorsais"],"secondaryMuscles":["biceps","antebracos","meio-das-costas"],"category":"forca","instructions":["Segure a barra de pull-up com as palmas voltadas para você e as mãos mais próximas que a largura dos ombros.","Com os braços estendidos, mantenha o tronco reto, arqueie levemente a lombar e projete o peito para fora. Esta é a posição inicial.","Puxe o tronco para cima expirando, até que o queixo passe a barra, focando no uso do bíceps e mantendo os cotovelos próximos ao corpo.","Mantenha a contração por um segundo e depois abaixe o tronco lentamente até os braços ficarem estendidos, inspirando."],"tracking":"reps"},{"id":"Pullups","name":"Barra Fixa","force":"pull","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["dorsais"],"secondaryMuscles":["biceps","meio-das-costas"],"category":"forca","instructions":["Segure a barra com as palmas para frente na pegada escolhida: larga (mãos além dos ombros), média (na largura dos ombros) ou fechada (mais próxima).","Com braços estendidos, incline o tronco para trás cerca de 30 graus, arqueando levemente as costas e projetando o peito. Esta é a posição inicial.","Puxe o tronco para cima até a barra tocar o peito, puxando ombros e braços para baixo e para trás. Exale. Contraia as costas no topo; mantenha o tronco estático, apenas os braços se movem.","Após um segundo, inspire e abaixe-se lentamente até os braços ficarem estendidos e os dorsais alongados."],"tracking":"reps"},{"id":"V-Bar_Pullup","name":"Barra Fixa com Barra V","force":"pull","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["dorsais"],"secondaryMuscles":["biceps","meio-das-costas","ombros"],"category":"forca","instructions":["Prenda a barra V no meio da barra de pull-up, com as alças voltadas para baixo.","Segure a barra V de cada lado e pendure-se nela. Estufe o peito e incline-se levemente para trás.","Puxe o tronco para cima usando os dorsais, inclinando a cabeça para trás para evitar bater no queixo. Continue até o peito quase tocar a barra. Expire durante o movimento.","Segure por um segundo e abaixe o corpo lentamente à posição inicial, inspirando."],"tracking":"reps"},{"id":"Cable_Incline_Pushdown","name":"Tríceps Pulley Inclinado","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["dorsais"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se em um banco inclinado de costas para uma polia alta com barra reta.","Segure a barra com pegada pronada (palmas para baixo) na largura dos ombros e estenda os braços à frente, perto das coxas. Esta é a posição inicial.","Mantenha os braços superiores parados e levante-os em um semicírculo até a barra ficar acima da cabeça, inspirando.","Retorne à posição inicial usando os dorsais, expirando e contraindo."],"tracking":"weight_reps"},{"id":"Straight-Arm_Pulldown","name":"Pulldown com Braços Retos","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["dorsais"],"secondaryMuscles":[],"category":"forca","instructions":["Segure a barra larga na polia alta de uma máquina de pulldown com pegada pronada (palmas para baixo) mais larga que os ombros. Dê dois passos para trás.","Incline o tronco para a frente cerca de 30 graus, com os braços totalmente estendidos e cotovelos levemente flexionados. Contraia os dorsais para iniciar.","Mantendo os braços retos, puxe a barra para baixo contraindo os dorsais até as mãos ficarem próximas às coxas, expirando.","Retorne à posição inicial mantendo os braços retos, inspirando."],"tracking":"weight_reps"},{"id":"Wide-Grip_Lat_Pulldown","name":"Pulldown com Pegada Larga","force":"pull","level":"iniciante","mechanic":"composto","equipment":"cabo","primaryMuscles":["dorsais"],"secondaryMuscles":["biceps","meio-das-costas","ombros"],"category":"forca","instructions":["Sente-se na máquina de pulldown com a barra larga presa à polia alta. Ajuste o apoio de joelhos para sua altura.","Segure a barra com as palmas voltadas para frente e as mãos mais afastadas que a largura dos ombros.","Com os braços estendidos, incline o tronco cerca de 30 graus para trás, arqueando a lombar e projetando o peito. Esta é a posição inicial.","Expire e puxe a barra para baixo até tocar a parte superior do peito, contraindo as costas. Mantenha o tronco imóvel e use apenas os braços."],"tracking":"weight_reps"},{"id":"Underhand_Cable_Pulldowns","name":"Pulldown com Pegada Supinada","force":"pull","level":"iniciante","mechanic":"composto","equipment":"cabo","primaryMuscles":["dorsais"],"secondaryMuscles":["biceps","meio-das-costas","ombros"],"category":"forca","instructions":["Sente-se no aparelho de pulldown com a barra larga. Ajuste o apoio de joelhos para sua altura.","Segure a barra com as palmas voltadas para você (pegada supinada), mãos mais próximas que a largura dos ombros.","Incline o tronco levemente para trás, arqueie as costas e estufe o peito.","Puxe a barra até o peito, contraindo as costas e mantendo os cotovelos próximos ao corpo."],"tracking":"weight_reps"},{"id":"V-Bar_Pulldown","name":"Puxada no Pulley com Barra V","force":"pull","level":"intermediario","mechanic":"composto","equipment":"cabo","primaryMuscles":["dorsais"],"secondaryMuscles":["biceps","meio-das-costas","ombros"],"category":"forca","instructions":["Sente-se na máquina de puxada com a barra V presa à polia superior.","Ajuste o apoio de joelhos para sua altura para evitar que o corpo seja levantado.","Segure a barra V com as palmas voltadas uma para a outra (pegada neutra). Estufe o peito e incline-se levemente para trás para ativar melhor os dorsais.","Puxe a barra para baixo usando os dorsais, contraindo as escápulas até o peito quase tocar a barra. Expire durante o movimento."],"tracking":"weight_reps"},{"id":"Elevated_Cable_Rows","name":"Remada no Pulley com Elevação","force":"pull","level":"intermediario","mechanic":"composto","equipment":"cabo","primaryMuscles":["dorsais"],"secondaryMuscles":["meio-das-costas","trapezio"],"category":"forca","instructions":["Use uma plataforma de 10 a 15 cm de altura e coloque-a no assento da máquina de remada sentada.","Sente-se na máquina e apoie os pés na plataforma frontal ou na barra, com os joelhos ligeiramente flexionados.","Incline o tronco para frente, mantendo a curvatura natural das costas, e segure a alça em V.","Com os braços estendidos, puxe até o tronco formar um ângulo de 90 graus com as pernas, costas ligeiramente arqueadas e peito para fora. Sinta o alongamento nas costas. Esta é a posição inicial."],"tracking":"weight_reps"},{"id":"Full_Range-Of-Motion_Lat_Pulldown","name":"Pulldown com Amplitude Completa","force":"pull","level":"intermediario","mechanic":"composto","equipment":"cabo","primaryMuscles":["dorsais"],"secondaryMuscles":["biceps","meio-das-costas","ombros"],"category":"forca","instructions":["Em pé ou sentado em um banco alto, segure as alças dos cabos altos com as mãos cruzadas, palmas para frente.","Mantendo o peito para cima e uma leve arqueada na lombar, puxe as alças para baixo em um movimento de arco. Gire as mãos para que no final as palmas fiquem voltadas uma para a outra. Retorne lentamente e repita."],"tracking":"weight_reps"},{"id":"Close-Grip_Front_Lat_Pulldown","name":"Pulldown Frente em Pegada Fechada","force":"pull","level":"iniciante","mechanic":"composto","equipment":"cabo","primaryMuscles":["dorsais"],"secondaryMuscles":["biceps","meio-das-costas","ombros"],"category":"forca","instructions":["Sente-se em uma máquina de pulldown com uma barra larga presa à polia superior. Ajuste o apoio de joelhos para sua altura; ele evitará que seu corpo seja levantado pela resistência.","Segure a barra com as palmas voltadas para a frente, usando uma pegada fechada (mãos mais próximas que a largura dos ombros).","Com os braços estendidos à frente, incline o torso para trás cerca de 30 graus, curvando levemente a lombar e projetando o peito para fora. Esta é sua posição inicial.","Enquanto expira, puxe a barra para baixo até tocar a parte superior do peito, trazendo os ombros e a parte superior dos braços para baixo e para trás. Dica: Concentre-se em contrair os músculos das costas na posição contraída. O torso superior deve permanecer parado; apenas os braços se movem. Os antebraços só seguram a barra, não puxam."],"tracking":"weight_reps"},{"id":"Rope_Straight-Arm_Pulldown","name":"Pulldown com Corda e Braços Estendidos","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["dorsais"],"secondaryMuscles":[],"category":"forca","instructions":["Prenda uma corda a uma polia alta e selecione o peso. Fique a alguns passos de distância, com os pés escalonados, e segure a corda com as duas mãos.","Incline-se para frente a partir do quadril, mantendo as costas retas e os braços estendidos à frente. Esta é a posição inicial.","Mantendo os braços retos, puxe a corda para baixo até as coxas, estendendo os ombros.","Segure na parte inferior, contraindo as costas."],"tracking":"weight_reps"},{"id":"Bent-Arm_Barbell_Pullover","name":"Pullover com Barra e Braços Flexionados","force":"pull","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["dorsais"],"secondaryMuscles":["peito","dorsais","ombros","triceps"],"category":"forca","instructions":["Deite-se em um banco plano segurando uma barra com uma pegada na largura dos ombros.","Segure a barra reta sobre o peito com os braços flexionados. Esta será a posição inicial.","Mantendo os braços flexionados, abaixe o peso lentamente em um arco atrás da cabeça, inspirando, até sentir um alongamento no peito.","Traga a barra de volta à posição inicial pelo mesmo arco, expirando durante o movimento."],"tracking":"weight_reps"},{"id":"Leverage_Iso_Row","name":"Remada Isométrica na Máquina de Alavanca","force":"pull","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["dorsais"],"secondaryMuscles":["biceps","meio-das-costas"],"category":"forca","instructions":["Ajuste o peso e a altura do banco para que as alças fiquem na altura do peito. Segure-as com pegada neutra ou pronada. Esta é a posição inicial.","Puxe as alças em direção ao torso, retraindo as escápulas e flexionando os cotovelos.","Pause e retorne lentamente, evitando apoiar o peso completamente para manter a tensão."],"tracking":"weight_reps"},{"id":"Glute_Kickback","name":"Coice de Glúteo","force":"push","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["gluteos"],"secondaryMuscles":["isquiotibiais"],"category":"forca","instructions":["Ajoelhe-se no chão ou em um colchonete e incline o tronco para a frente, com os braços estendidos à sua frente (perpendiculares ao torso), para ficar em uma posição de flexão de braços ajoelhada, mas com os braços na largura dos ombros. Mantenha a cabeça olhando para a frente e os joelhos dobrados em um ângulo de 90 graus entre os isquiotibiais e as panturrilhas. Esta será sua posição inicial.","Ao expirar, levante a perna direita até que os isquiotibiais fiquem alinhados com as costas, mantendo o ângulo de 90 graus. Contraia os glúteos durante o movimento e segure a contração no topo por um segundo. Dica: No final do movimento, a coxa deve ficar paralela ao chão e a panturrilha perpendicular a ele.","Volte à posição inicial enquanto inspira e repita com a perna esquerda.","Continue alternando as pernas até completar as repetições recomendadas."],"tracking":"reps"},{"id":"One-Legged_Cable_Kickback","name":"Coice com Cabo e uma Perna","force":"push","level":"intermediario","mechanic":"isolado","equipment":"cabo","primaryMuscles":["gluteos"],"secondaryMuscles":["isquiotibiais"],"category":"forca","instructions":["Prenda uma tornozeira de couro a uma polia baixa e fixe-a ao seu tornozelo.","Fique de frente para a pilha de pesos, a cerca de 60 cm de distância, segurando a estrutura de aço para apoio.","Mantendo os joelhos e quadris levemente flexionados e o abdômen contraído, contraia os glúteos para \"chutar\" a perna ativa para trás em um arco semicircular, o mais alto possível, enquanto expira. Dica: Na extensão total, contraia os glúteos por um segundo para uma contração máxima.","Traga a perna ativa lentamente para frente, resistindo à tração do cabo até voltar à posição inicial."],"tracking":"weight_reps"},{"id":"Barbell_Hip_Thrust","name":"Elevação Pélvica com Barra","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["gluteos"],"secondaryMuscles":["panturrilhas","isquiotibiais"],"category":"powerlifting","instructions":["Sente-se no chão com um banco atrás de você. Coloque uma barra carregada sobre as pernas. Use uma barra mais grossa ou um apoio para reduzir o desconforto.","Role a barra até que fique diretamente sobre os quadris e incline-se no banco, apoiando as escápulas na parte superior.","Comece o movimento empurrando com os pés, elevando os quadris verticalmente. O peso deve ser suportado pelas escápulas e pés. Estenda o máximo possível e retorne à posição inicial."],"tracking":"weight_reps"},{"id":"Barbell_Glute_Bridge","name":"Elevação de Quadril com Barra","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["gluteos"],"secondaryMuscles":["panturrilhas","isquiotibiais"],"category":"powerlifting","instructions":["Sente-se no chão com uma barra carregada sobre as pernas. Use uma barra acolchoada para maior conforto. Role a barra até que fique diretamente acima dos quadris e deite-se de costas no chão.","Inicie o movimento empurrando com os calcanhares, elevando os quadris verticalmente através da barra. O peso deve ser suportado pela parte superior das costas e pelos calcanhares.","Estenda o máximo possível, depois reverta o movimento para retornar à posição inicial."],"tracking":"weight_reps"},{"id":"Barbell_Deadlift","name":"Levantamento Terra com Barra","force":"pull","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["inferior-das-costas"],"secondaryMuscles":["panturrilhas","antebracos","gluteos","isquiotibiais","dorsais","meio-das-costas","quadriceps","trapezio"],"category":"forca","instructions":["Fique em frente a uma barra carregada.","Mantendo as costas o mais retas possível, dobre os joelhos, incline-se para frente e segure a barra com uma pegada média (largura dos ombros) com as palmas para baixo. Esta será sua posição inicial.","Segurando a barra, inicie o levantamento empurrando com as pernas e erguendo o tronco até a posição vertical enquanto expira. Na posição vertical, estufe o peito e contraia as costas, trazendo as escápulas para trás.","Volte à posição inicial dobrando os joelhos e inclinando o tronco para frente, mantendo as costas retas. Quando os pesos tocarem o chão, você estará pronto para outra repetição."],"tracking":"weight_reps"},{"id":"Hyperextensions_With_No_Hyperextension_Bench","name":"Hiperextensões Sem Banco de Hiperextensão","force":"pull","level":"intermediario","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["inferior-das-costas"],"secondaryMuscles":["gluteos","isquiotibiais"],"category":"forca","instructions":["Com alguém segurando suas pernas, deslize-se para a borda de um banco plano até que os quadris fiquem suspensos no final do banco. Dica: Todo o tronco deve estar pendurado em direção ao chão. O movimento será mais curto devido à altura do banco.","Com o corpo reto, cruze os braços na frente do peito ou atrás da cabeça. Esta será a posição inicial. Dica: Você pode segurar um peso extra para mais resistência.","Incline-se lentamente para frente na cintura o máximo possível, mantendo as costas retas. Inspire ao fazer isso. Continue até quase tocar o chão ou sentir um alongamento nos isquiotibiais. Dica: Nunca arredonde as costas.","Levante lentamente o tronco de volta à posição inicial enquanto expira. Dica: Evite arquear as costas além da linha reta e não balance o tronco."],"tracking":"reps"},{"id":"Lying_Leg_Curls","name":"Cadeira Flexora","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["isquiotibiais"],"secondaryMuscles":[],"category":"forca","instructions":["Ajuste a alavanca da máquina para sua altura e deite-se de bruços na cadeira flexora, com a almofada na parte de trás das pernas (alguns centímetros abaixo das panturrilhas). Dica: Prefira máquinas anguladas, pois são melhores para recrutar os isquiotibiais.","Mantendo o torso plano no banco, certifique-se de que as pernas estejam totalmente estendidas e segure as alças laterais da máquina. Posicione os pés retos (ou use outras variações de posicionamento). Esta será sua posição inicial.","Ao expirar, flexione as pernas o máximo possível sem levantar as coxas do banco. Ao atingir a posição totalmente contraída, segure por um segundo.","Ao inspirar, retorne as pernas à posição inicial. Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Reverse_Hyperextension","name":"Hiperextensão Reversa","force":"pull","level":"intermediario","mechanic":null,"equipment":"maquina","primaryMuscles":["isquiotibiais"],"secondaryMuscles":["panturrilhas","gluteos"],"category":"forca","instructions":["Posicione os pés entre as almofadas após colocar o peso adequado. Deite-se na almofada superior, com os quadris para fora da borda, e segure as alças para se firmar.","Para iniciar o movimento, flexione os quadris, puxando as pernas para frente.","Inverta o movimento estendendo os quadris, empurrando as pernas para trás. É importante não hiperestender o quadril; pare antes do limite máximo da amplitude.","Retorne flexionando os quadris novamente, puxando o carrinho o mais para frente possível."],"tracking":"weight_reps"},{"id":"Standing_Leg_Curl","name":"Flexão de Pernas em Pé","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["isquiotibiais"],"secondaryMuscles":[],"category":"forca","instructions":["Ajuste a máquina à sua altura, incline o tronco para a frente e posicione a perna direita no aparelho, com o apoio atrás da panturrilha.","Segure as alças, mantenha a perna estendida e os dedos retos. Esta é a posição inicial.","Flexione a perna para cima o máximo possível enquanto expira, sem levantar a coxa.","Segure a contração por um segundo e retorne à posição inicial enquanto inspira."],"tracking":"weight_reps"},{"id":"Seated_Leg_Curl","name":"Cadeira Flexora Sentada","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["isquiotibiais"],"secondaryMuscles":[],"category":"forca","instructions":["Ajuste a alavanca da máquina para sua altura e sente-se com as costas apoiadas no encosto.","Coloque a parte de trás da perna no apoio acolchoado e fixe a almofada nas coxas. Segure as alças laterais com as pernas estendidas. Esta é a posição inicial.","Flexione os joelhos para puxar a alavanca em direção às coxas, expirando. Mantenha o tronco parado e segure a contração por um segundo.","Volte lentamente à posição inicial, inspirando."],"tracking":"weight_reps"},{"id":"Romanian_Deadlift","name":"Levantamento Terra Romeno","force":"pull","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["isquiotibiais"],"secondaryMuscles":["panturrilhas","gluteos","inferior-das-costas"],"category":"forca","instructions":["Segure uma barra com as palmas voltadas para baixo e as mãos um pouco além da largura dos ombros.","Flexione levemente os joelhos, mantenha as canelas verticais, os quadris para trás e as costas retas. Esta é a posição inicial.","Mantendo as costas e braços retos, use os quadris para levantar a barra ao expirar, em um movimento controlado.","Ao ficar em pé completamente, abaixe a barra empurrando os quadris para trás, flexionando os joelhos minimamente."],"tracking":"weight_reps"},{"id":"Smith_Machine_Stiff-Legged_Deadlift","name":"Stiff-Legged Deadlift no Smith","force":"pull","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["isquiotibiais"],"secondaryMuscles":["gluteos","inferior-das-costas"],"category":"forca","instructions":["Ajuste a barra na máquina Smith para a altura das coxas. Com a barra carregada, segure-a com as palmas para frente e as mãos na largura dos ombros. Use straps se necessário.","Levante a barra estendendo os braços, mantendo as costas retas. Fique em pé com as pernas na largura dos ombros ou mais estreitas e joelhos levemente flexionados. Esta é a posição inicial.","Mantendo os joelhos imóveis, abaixe a barra em direção aos pés dobrando a cintura, com as costas retas. Desça até sentir o alongamento nos isquiotibiais. Expire durante esse movimento.","Volte o tronco à posição ereta estendendo os quadris e a cintura. Inspire durante esse movimento."],"tracking":"weight_reps"},{"id":"Lunge_Pass_Through","name":"Afundo com Passagem de Kettlebell","force":"push","level":"intermediario","mechanic":"composto","equipment":"kettlebell","primaryMuscles":["isquiotibiais"],"secondaryMuscles":["panturrilhas","gluteos","quadriceps"],"category":"forca","instructions":["Fique em pé com o tronco ereto, segurando um kettlebell na mão direita. Esta será a posição inicial.","Dê um passo à frente com o pé esquerdo e abaixe o tronco flexionando o quadril e o joelho, mantendo o tronco ereto. Abaixe o joelho traseiro até quase tocar o chão.","Durante o afundo, passe o kettlebell sob a perna da frente para a mão oposta.","Empurrando pelo calcanhar, retorne à posição inicial."],"tracking":"weight_reps"},{"id":"Stiff-Legged_Barbell_Deadlift","name":"Levantamento Terra com Pernas Rígidas","force":"pull","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["isquiotibiais"],"secondaryMuscles":["gluteos","inferior-das-costas"],"category":"forca","instructions":["Segure uma barra com pegada pronada (palmas para baixo). Talvez seja necessário usar straps se usar muito peso.","Fique em pé com o tronco reto e as pernas afastadas na largura dos ombros ou menos. Os joelhos devem estar levemente flexionados. Esta é a posição inicial.","Mantendo os joelhos fixos, abaixe a barra em direção aos pés, flexionando os quadris e mantendo as costas retas. Continue até sentir um alongamento nos isquiotibiais. Inspire ao executar este movimento.","Volte o tronco à posição ereta, estendendo os quadris até a posição inicial. Expire ao executar este movimento."],"tracking":"weight_reps"},{"id":"Kettlebell_One-Legged_Deadlift","name":"Stiff-Legged com Kettlebell em Uma Perna","force":"pull","level":"intermediario","mechanic":"composto","equipment":"kettlebell","primaryMuscles":["isquiotibiais"],"secondaryMuscles":["gluteos","inferior-das-costas"],"category":"forca","instructions":["Segure um kettlebell pelo cabo com uma mão. Fique em uma perna, do mesmo lado que segura o kettlebell.","Com o joelho levemente flexionado, faça um stiff-legged, dobrando o quadril e estendendo a perna livre para trás para equilíbrio.","Continue abaixando o kettlebell até ficar paralelo ao chão e retorne à posição ereta."],"tracking":"weight_reps"},{"id":"Natural_Glute_Ham_Raise","name":"Elevação de Glúteos e Isquiotibiais Natural","force":"pull","level":"intermediario","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["isquiotibiais"],"secondaryMuscles":["panturrilhas","gluteos","inferior-das-costas"],"category":"forca","instructions":["Use a almofada de pernas de uma máquina de pulley ou um banco de preacher. Posicione-se com os tornozelos sob as almofadas, joelhos no assento, e de costas para a máquina. Mantenha-se ereto com boa postura. Esta será a posição inicial.","Abaixe-se com controle até que os joelhos estejam quase totalmente estendidos.","Com controle, levante-se de volta à posição inicial.","Se não conseguir completar uma repetição, use uma faixa elástica, a ajuda de um parceiro ou empurre-se de uma caixa para auxiliar."],"tracking":"reps"},{"id":"Stiff-Legged_Dumbbell_Deadlift","name":"Levantamento Terra com Halteres Pernas Estendidas","force":"pull","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["isquiotibiais"],"secondaryMuscles":["gluteos","inferior-das-costas"],"category":"forca","instructions":["Segure um par de halteres ao lado do corpo com os braços estendidos.","Fique em pé com o tronco reto e as pernas afastadas na largura dos ombros ou menos, com os joelhos levemente flexionados. Esta é a posição inicial.","Mantendo os joelhos fixos, incline o tronco para a frente, mantendo as costas retas, e abaixe os halteres em direção aos pés até sentir um alongamento nos isquiotibiais. Expire durante esse movimento.","Retorne o tronco à posição inicial estendendo os quadris e a cintura. Inspire durante esse movimento."],"tracking":"weight_reps"},{"id":"Lying_T-Bar_Row","name":"Remada T-Bar Deitado","force":"pull","level":"intermediario","mechanic":"composto","equipment":"maquina","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais"],"category":"forca","instructions":["Carregue a máquina de Remada T-Bar com o peso desejado e ajuste a altura das pernas para que o peito superior fique no topo da almofada. Dica: Em algumas máquinas, basta pisar no degrau apropriado.","Deite-se de bruços na almofada e segure as alças. Use pegada pronada, supinada ou neutra, dependendo da parte das costas que deseja enfatizar.","Levante a barra do suporte e estenda os braços à sua frente. Esta será sua posição inicial.","Expirando, puxe o peso para cima lentamente e contraia as costas no topo do movimento. Dica: Mantenha os braços superiores próximos ao torso para melhor ativação muscular, não levante o corpo da almofada e evite usar os bíceps."],"tracking":"weight_reps"},{"id":"T-Bar_Row_with_Handle","name":"Remada em T com Pegador","force":"pull","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais"],"category":"forca","instructions":["Posicione uma barra em um suporte de landmine ou canto para evitar que ela se mova. Coloque o peso adequado na extremidade.","Fique sobre a barra e coloque um pegador duplo em D ao redor da barra, próximo à rosca. Use os quadris e as pernas para levantar-se até ficar em pé.","Adote uma postura ampla, com os quadris para trás e o peito erguido. Os braços devem estar estendidos. Esta é a posição inicial.","Puxe o peso em direção ao abdômen superior, retraindo as escápulas e flexionando os cotovelos. Evite movimentos bruscos ou trapaça."],"tracking":"weight_reps"},{"id":"Bent_Over_Barbell_Row","name":"Remada Curvada com Barra","force":"pull","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais","ombros"],"category":"forca","instructions":["Segure uma barra com pegada pronada (palmas para baixo), flexione levemente os joelhos e incline o tronco para a frente, mantendo as costas retas até ficar quase paralelo ao chão. Dica: Mantenha a cabeça erguida. A barra deve ficar pendurada à sua frente, com os braços perpendiculares ao chão. Esta é a posição inicial.","Mantendo o tronco parado, expire e puxe a barra em sua direção. Mantenha os cotovelos próximos ao corpo e use apenas os antebraços para segurar o peso. No topo, contraia as costas e segure brevemente.","Inspire e abaixe a barra lentamente à posição inicial.","Repita para a quantidade recomendada de repetições."],"tracking":"weight_reps"},{"id":"Seated_Cable_Rows","name":"Remada Sentada no Pulley","force":"pull","level":"iniciante","mechanic":"composto","equipment":"cabo","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais","ombros"],"category":"forca","instructions":["Sente-se na máquina de remada com barra em V. Apoie os pés na plataforma, com joelhos levemente flexionados.","Incline-se para frente, mantendo as costas alinhadas, e segure a barra V.","Puxe a barra até o torso ficar a 90 graus das pernas, com as costas levemente arqueadas e o peito para fora. Sinta o alongamento nas costas. Esta é a posição inicial.","Mantenha o torso imóvel e puxe a barra em direção ao abdômen, mantendo os braços próximos ao corpo. Expire ao puxar."],"tracking":"weight_reps"},{"id":"Incline_Bench_Pull","name":"Puxada em Banco Inclinado","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["dorsais","ombros"],"category":"forca","instructions":["Pegue um halter em cada mão e deite-se de bruços em um banco inclinado a aproximadamente 30 graus.","Deixe os braços pendurados ao lado do corpo, totalmente estendidos em direção ao chão.","Gire os pulsos para uma pegada pronada (palmas para baixo).","Abra os cotovelos para os lados. Esta será a posição inicial."],"tracking":"weight_reps"},{"id":"Reverse_Grip_Bent-Over_Rows","name":"Remada Invertida com Barra","force":"pull","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais","ombros"],"category":"forca","instructions":["Fique em pé segurando uma barra com pegada supinada (palmas voltadas para cima).","Dobre levemente os joelhos e incline o tronco para frente, flexionando o quadril, mantendo as costas retas até ficar quase paralelo ao chão. Dica: Mantenha a cabeça erguida. A barra deve ficar pendurada à sua frente, com os braços perpendiculares ao chão e ao tronco. Esta é a posição inicial.","Mantendo o tronco imóvel, puxe a barra para cima enquanto expira, mantendo os cotovelos próximos ao corpo e sem forçar com os antebraços, apenas segurando o peso. Na posição contraída, contraia os músculos das costas e segure por um segundo.","Abaixe lentamente o peso de volta à posição inicial enquanto inspira."],"tracking":"weight_reps"},{"id":"Middle_Back_Shrug","name":"Encolhimento de Costas Médias","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"halteres","primaryMuscles":["meio-das-costas"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se de bruços em um banco inclinado, segurando um halter em cada mão. Seus braços devem estar totalmente estendidos para baixo, apontando para o chão. As palmas das mãos devem estar voltadas uma para a outra. Esta será sua posição inicial.","Ao expirar, aperte as escápulas juntas e mantenha a contração por um segundo completo. Dica: Este movimento é como o inverso de um abraço, ou tentar fazer elevações laterais posteriores como se não tivesse braços.","Ao inspirar, volte à posição inicial.","Repita para a quantidade recomendada de repetições."],"tracking":"weight_reps"},{"id":"Dumbbell_Incline_Row","name":"Remada Inclinada com Halteres","force":"pull","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","antebracos","dorsais","ombros"],"category":"forca","instructions":["Usando uma pegada neutra, incline-se em um banco inclinado.","Segure um halter em cada mão com pegada neutra, começando com os braços estendidos. Esta será a posição inicial.","Retraia as escápulas e flexione os cotovelos para puxar os halteres para o lado do corpo.","Faça uma pausa no topo do movimento e, em seguida, retorne à posição inicial."],"tracking":"weight_reps"},{"id":"Smith_Machine_Bent_Over_Row","name":"Remada Curvada no Smith Machine","force":"pull","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais","ombros"],"category":"forca","instructions":["Ajuste a barra do Smith machine a uma altura cerca de 5 cm abaixo dos joelhos.","Flexione levemente os joelhos e incline o tronco para a frente, dobrando-se na cintura, mantendo as costas retas até ficar quase paralelo ao chão. Dica: Mantenha a cabeça erguida.","Segure a barra com uma pegada pronada e solte-a do suporte. Deixe-a pendurar diretamente à sua frente, com os braços estendidos perpendicularmente ao chão e ao tronco. Esta é a posição inicial.","Mantendo o tronco imóvel, levante a barra ao expirar, mantendo os cotovelos próximos ao corpo sem usar a força dos antebraços, apenas segurando o peso. Na posição contraída, comprima os músculos das costas e segure por um segundo."],"tracking":"weight_reps"},{"id":"Bent_Over_Two-Dumbbell_Row","name":"Remada Curvada com Dois Halteres","force":"pull","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais","ombros"],"category":"forca","instructions":["Com um halter em cada mão (palmas voltadas para o torso), flexione levemente os joelhos e incline o tronco para frente, mantendo as costas retas até ficar quase paralelo ao chão. Os braços devem ficar perpendiculares ao solo. Esta é a posição inicial.","Com o tronco fixo, levante os halteres para os lados, mantendo os cotovelos próximos ao corpo. Expire ao levantar e contraia as costas no topo.","Abaixe os pesos lentamente à posição inicial enquanto inspira.","Repita o número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Straight_Bar_Bench_Mid_Rows","name":"Remada Curvada com Barra no Banco","force":"pull","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais"],"category":"forca","instructions":["Coloque uma barra carregada na extremidade de um banco. Fique em pé no banco atrás da barra, com pegada média e pronada. Mantenha os quadris para trás, peito erguido e coluna neutra. Esta é a posição inicial.","Puxe a barra em direção ao tronco, retraindo as escápulas e flexionando os cotovelos, com movimento controlado.","Após uma pausa breve, retorne lentamente a barra à posição inicial, estendendo completamente os braços."],"tracking":"weight_reps"},{"id":"One-Arm_Kettlebell_Row","name":"Remada com Kettlebell de Um Braço","force":"pull","level":"intermediario","mechanic":"composto","equipment":"kettlebell","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais"],"category":"forca","instructions":["Posicione um kettlebell na frente dos pés. Flexione levemente os joelhos e empurre o quadril para trás o máximo possível ao se inclinar para frente para assumir a posição inicial.","Segure o kettlebell e puxe-o em direção ao estômago, retraindo a escápula e flexionando o cotovelo. Mantenha as costas retas. Abaixe e repita."],"tracking":"weight_reps"},{"id":"Leverage_High_Row","name":"Remada Alta na Máquina de Alavanca","force":"pull","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["dorsais"],"category":"forca","instructions":["Ajuste o peso e a altura do banco para alcançar as alças acima de você. Use o apoio de joelhos para estabilidade. Segure as alças com pegada pronada. Esta é a posição inicial.","Puxe as alças em direção ao torso, retraindo as escápulas e flexionando os cotovelos.","Pause brevemente e retorne lentamente às alças à posição inicial, mantendo a tensão."],"tracking":"weight_reps"},{"id":"Lying_Cambered_Barbell_Row","name":"Remada com Barra Camberada Deitado","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais","trapezio"],"category":"forca","instructions":["Coloque uma barra camberada sob um banco de exercícios.","Deite-se de bruços no banco e segure a barra com uma pegada pronada (palmas para baixo) mais larga que os ombros. Esta será a posição inicial.","Ao expirar, puxe a barra para cima mantendo os cotovelos próximos ao corpo, em direção ao peito (para focar a parte superior das costas) ou ao estômago (para os dorsais).","Segure por um segundo no topo e retorne lentamente à posição inicial enquanto inspira."],"tracking":"weight_reps"},{"id":"Two-Arm_Kettlebell_Row","name":"Remada com Kettlebell de Dois Braços","force":"pull","level":"intermediario","mechanic":"composto","equipment":"kettlebell","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais"],"category":"forca","instructions":["Coloque dois kettlebells à frente dos pés. Flexione levemente os joelhos e incline o tronco para frente, mantendo as costas retas.","Segure os kettlebells e puxe-os em direção ao estômago, retraindo as escápulas e flexionando os cotovelos.","Abaixe e repita."],"tracking":"weight_reps"},{"id":"Bent_Over_Two-Dumbbell_Row_With_Palms_In","name":"Remada Curvada com Dois Halteres e Palmas para Dentro","force":"pull","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["meio-das-costas"],"secondaryMuscles":["biceps","dorsais"],"category":"forca","instructions":["Com um halter em cada mão (palmas voltadas uma para a outra), incline-se para frente com o tronco quase paralelo ao chão, mantendo as costas retas. Os braços ficam perpendiculares ao solo. Esta é a posição inicial.","Com o tronco fixo, levante os halteres para os lados, expirando e apertando as escápulas. Contraia as costas no topo.","Abaixe os pesos lentamente à posição inicial enquanto inspira.","Repita o número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Face_Pull","name":"Face Pull","force":"pull","level":"intermediario","mechanic":"composto","equipment":"cabo","primaryMuscles":["ombros"],"secondaryMuscles":["meio-das-costas"],"category":"forca","instructions":["Fique de frente para uma polia alta com uma corda ou alças duplas. Puxe o peso diretamente em direção ao seu rosto, separando as mãos ao fazê-lo. Mantenha os braços superiores paralelos ao chão."],"tracking":"weight_reps"},{"id":"Reverse_Flyes","name":"Crucifixo Inverso","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se em um banco inclinado com o peito e o estômago pressionados contra o encosto. Segure halteres com as palmas voltadas uma para a outra (pegada neutra).","Estenda os braços à frente, perpendicularmente ao banco. As pernas devem ficar firmes, com a pressão nas pontas dos pés. Esta é a posição inicial.","Mantendo os cotovelos levemente flexionados, mova os pesos para os lados em um arco enquanto expira. Dica: Contraia as escápulas para melhores resultados.","Eleve os braços até ficarem paralelos ao chão."],"tracking":"weight_reps"},{"id":"Upright_Barbell_Row","name":"Remada Alta com Barra","force":"pull","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["ombros"],"secondaryMuscles":["trapezio"],"category":"forca","instructions":["Segure uma barra com pegada pronada, mãos ligeiramente mais próximas que a largura dos ombros. Braços estendidos, barra sobre as coxas.","Eleve a barra puxando os cotovelos para cima e para os lados, mantendo-a próxima ao corpo até quase tocar o queixo.","Abaixe a barra lentamente e repita."],"tracking":"weight_reps"},{"id":"Cable_Shoulder_Press","name":"Desenvolvimento no Pulley","force":"push","level":"iniciante","mechanic":"composto","equipment":"cabo","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Ajuste os cabos para a parte inferior das torres e selecione um peso adequado.","Fique em pé entre as torres. Segure os cabos na altura dos ombros, com as palmas voltadas para frente. Esta é a posição inicial.","Mantendo a cabeça e o peito erguidos, estenda os cotovelos para empurrar as alças diretamente acima da cabeça.","Após uma pausa no topo, retorne à posição inicial e repita."],"tracking":"weight_reps"},{"id":"Cable_Rear_Delt_Fly","name":"Crucifixo Inverso na Polia","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["ombros"],"secondaryMuscles":[],"category":"forca","instructions":["Ajuste as polias para uma altura acima da cabeça e selecione o peso.","Segure a polia esquerda com a mão direita e a polia direita com a mão esquerda, cruzando os braços à frente. Esta é a posição inicial.","Movimente os braços para trás e para os lados, mantendo-os estendidos.","Faça uma pausa no final do movimento antes de retornar as alças à posição inicial."],"tracking":"weight_reps"},{"id":"Front_Cable_Raise","name":"Elevação Frontal no Pulley","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["ombros"],"secondaryMuscles":[],"category":"forca","instructions":["Selecione o peso em uma máquina de pulley baixo e segure a alça com uma mão.","Fique de costas para o pulley, com o braço estendido para baixo e a alça na frente das coxas, palmas voltadas para as coxas. Esta é a posição inicial.","Mantendo o tronco imóvel, levante o braço para a frente com o cotovelo levemente flexionado e palmas para baixo, até o braço ficar ligeiramente acima do paralelo. Expire e pause no topo.","Inspire, abaixando o braço lentamente à posição inicial."],"tracking":"weight_reps"},{"id":"Front_Dumbbell_Raise","name":"Elevação Frontal com Halteres","force":"push","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":[],"category":"forca","instructions":["Segure um halter em cada mão, fique em pé com o tronco reto e os halteres na frente das coxas, braços estendidos, palmas voltadas para as coxas. Esta é a posição inicial.","Mantendo o tronco imóvel, levante o halter esquerdo para a frente com o cotovelo levemente flexionado e palmas para baixo, até o braço ficar ligeiramente acima do paralelo. Expire e pause no topo.","Abaixe o halter esquerdo lentamente enquanto levanta o direito, alternando os movimentos.","Continue alternando até completar as repetições recomendadas para cada braço."],"tracking":"weight_reps"},{"id":"Dumbbell_Raise","name":"Elevação Lateral com Halteres","force":"pull","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":["biceps"],"category":"forca","instructions":["Segure um halter em cada mão e fique em pé com os braços estendidos ao lado do corpo, cotovelos levemente flexionados e costas retas. Os halteres devem ficar próximos às coxas, com as palmas das mãos voltadas para trás.","Expire e use os ombros para levantar os halteres para os lados, até eles ficarem próximos ao queixo, com os cotovelos conduzindo o movimento. Pause por um segundo no topo.","Inspire e abaixe os halteres lentamente até a posição inicial.","Repita para a quantidade recomendada de repetições."],"tracking":"weight_reps"},{"id":"Side_Laterals_to_Front_Raise","name":"Elevação Lateral para Frontal","force":"push","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":["trapezio"],"category":"forca","instructions":["Em pé, segure um par de halteres ao lado do corpo. Esta é a posição inicial.","Mantendo os cotovelos levemente flexionados, levante os pesos diretamente à frente até a altura dos ombros, evitando balanços ou trapaças.","No topo do movimento, mova os pesos para a frente, mantendo os braços estendidos.","Abaixe os pesos com controle."],"tracking":"weight_reps"},{"id":"Reverse_Machine_Flyes","name":"Crucifixo Invertido na Máquina","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["ombros"],"secondaryMuscles":[],"category":"forca","instructions":["Ajuste as alças para trás. Selecione o peso adequado e ajuste a altura do banco para que as alças fiquem na altura dos ombros. Segure as alças com as mãos voltadas para dentro. Esta é a posição inicial.","Em um movimento semicircular, puxe as mãos para os lados e para trás, contraindo os deltoides posteriores.","Mantenha os braços levemente flexionados durante todo o movimento, com toda a ação ocorrendo na articulação do ombro.","Faça uma pausa no final do movimento e retorne lentamente o peso à posição inicial."],"tracking":"weight_reps"},{"id":"Machine_Shoulder_Military_Press","name":"Desenvolvimento Militar Máquina","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Sente-se na Máquina de Desenvolvimento e selecione o peso.","Segure as alças ao lado do corpo, com os cotovelos flexionados e alinhados com o torso. Esta será sua posição inicial.","Levante as alças, expirando e estendendo os braços completamente. Segure a contração por um segundo no topo.","Abaixe as alças lentamente à posição inicial, inspirando."],"tracking":"weight_reps"},{"id":"Barbell_Shoulder_Press","name":"Desenvolvimento Militar com Barra","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["ombros"],"secondaryMuscles":["peito","triceps"],"category":"forca","instructions":["Sente-se em um banco com apoio dorsal em um rack de agachamento. Posicione a barra logo acima da cabeça. Segure a barra com pegada pronada (palmas para frente).","Após pegar a barra, levante-a acima da cabeça travando os braços. Segure na altura dos ombros e ligeiramente à frente da cabeça. Esta é a posição inicial.","Abaixe a barra lentamente até os ombros inspirando.","Levante a barra de volta à posição inicial expirando."],"tracking":"weight_reps"},{"id":"Cable_Seated_Lateral_Raise","name":"Elevação Lateral Sentado na Polia","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["ombros"],"secondaryMuscles":["meio-das-costas","trapezio"],"category":"forca","instructions":["Posicione-se entre duas polias baixas opostas, com um banco plano atrás de você (perpendicular). Selecione o peso em cada polia.","Sente-se na borda do banco, com os pés à frente dos joelhos.","Incline-se para frente mantendo as costas retas e apoie o torso nas coxas.","Peça para alguém entregar as alças. Segure a polia esquerda com a mão direita e a direita com a esquerda. Os cabos devem passar sob os joelhos, com os braços estendidos, palmas viradas uma para a outra e cotovelos levemente flexionados. Esta é a posição inicial."],"tracking":"weight_reps"},{"id":"Seated_Dumbbell_Press","name":"Desenvolvimento com Halter Sentado","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Pegue um par de halteres e sente-se em um banco de desenvolvimento militar ou um banco utilitário com encosto, colocando os halteres em pé sobre as coxas.","Levante os halteres um de cada vez usando as coxas para trazê-los à altura dos ombros em cada lado.","Gire os pulsos para que as palmas das mãos fiquem voltadas para a frente. Esta é a posição inicial.","Ao expirar, empurre os halteres para cima até que se toquem no topo."],"tracking":"weight_reps"},{"id":"Standing_Dumbbell_Press","name":"Desenvolvimento com Halteres em Pé","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Em pé, com os pés na largura dos ombros, segure um halter em cada mão. Levante os halteres até a altura da cabeça, com os cotovelos para fora e cerca de 90 graus. Esta é a posição inicial.","Mantendo a técnica rigorosa, sem impulso das pernas ou inclinar para trás, estenda os cotovelos para levantar os pesos juntos acima da cabeça.","Faça uma pausa e retorne lentamente à posição inicial."],"tracking":"weight_reps"},{"id":"Front_Two-Dumbbell_Raise","name":"Elevação Frontal com Dois Halteres","force":"push","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":[],"category":"forca","instructions":["Segure dois halteres e fique em pé com o torso reto, os halteres na frente das coxas com os braços estendidos e palmas voltadas para as coxas. Esta é a posição inicial.","Mantendo o torso imóvel, levante os halteres para frente com os cotovelos ligeiramente flexionados e palmas para baixo, até os braços ficarem ligeiramente acima da paralela com o chão. Expire no movimento e pause no topo.","Abaixe os halteres lentamente à posição inicial enquanto inspira.","Repita para a quantidade recomendada de repetições."],"tracking":"weight_reps"},{"id":"Lying_One-Arm_Lateral_Raise","name":"Elevação Lateral com Halter Deitado","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":[],"category":"forca","instructions":["Segurando um halter em uma mão, deite-se de bruços em um banco plano. Use a outra mão para segurar a perna do banco para estabilidade.","Posicione a palma da mão que segura o halter de forma neutra (voltada para o torso), com o braço estendido e o cotovelo ligeiramente flexionado. Esta será sua posição inicial.","Ao expirar, levante o braço com o halter para o lado até o cotovelo estar na altura do ombro e o braço aproximadamente paralelo ao chão. Dica: Mantenha o braço perpendicular ao torso e estendido; segure a contração no topo por um segundo.","Ao inspirar, abaixe lentamente o halter à posição inicial."],"tracking":"weight_reps"},{"id":"Reverse_Flyes_With_External_Rotation","name":"Crucifixo Inverso com Rotação Externa","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se em um banco inclinado a 30 graus com o peito e o estômago pressionados contra o encosto.","Segure halteres com as palmas voltadas para baixo. Os braços devem estar à frente, perpendicularmente ao banco, com cotovelos levemente flexionados. As pernas firmes, pressionando as pontas dos pés (calcanhares fora do chão). Esta é a posição inicial.","Mantendo os cotovelos flexionados, mova os pesos para os lados em um arco enquanto expira.","Ao levantar, gire os punhos externamente em 90 graus, passando de palmas para baixo (pronada) para palmas uma para a outra (neutra). Dica: Contraia as escápulas."],"tracking":"weight_reps"},{"id":"Dumbbell_Shoulder_Press","name":"Desenvolvimento de Ombros com Halteres","force":"push","level":"intermediario","mechanic":"composto","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Sentado em um banco com apoio para as costas, segure um halter em cada mão, apoiados verticalmente sobre as coxas.","Levante os halteres até a altura dos ombros, um de cada vez, usando as coxas para auxiliar no movimento.","Gire os pulsos para que as palmas das mãos fiquem voltadas para frente. Esta é sua posição inicial.","Expire e empurre os halteres para cima até que se toquem no topo."],"tracking":"weight_reps"},{"id":"Standing_Low-Pulley_Deltoid_Raise","name":"Elevação Lateral com Polia Baixa em Pé","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["ombros"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Fique ao lado direito da polia baixa, segure a alça com a mão esquerda em pegada pronada e apoie-se com a mão direita.","Mantenha as costas retas e os pés na largura dos ombros. Esta é a posição inicial.","Eleve a alça com a mão esquerda até a altura do ombro enquanto expira.","Sinta a contração no topo e abaixe lentamente à posição inicial enquanto inspira."],"tracking":"weight_reps"},{"id":"Smith_Machine_Overhead_Shoulder_Press","name":"Desenvolvimento Militar no Smith Machine","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Posicione um banco plano (de preferência com encosto) sob o Smith Machine. Ajuste a barra para que, ao sentar no banco, os braços precisem estar quase totalmente estendidos para alcançá-la.","Sente-se ligeiramente atrás da barra, formando uma linha reta imaginária do nariz à barra. Pés firmes no chão. Pegue a barra com as palmas para frente, desengate-a e levante até os braços ficarem totalmente estendidos. Esta é a posição inicial.","Inspire e abaixe lentamente a barra até a altura do queixo.","Levante a barra de volta à posição inicial usando os ombros enquanto expira."],"tracking":"weight_reps"},{"id":"Seated_Barbell_Military_Press","name":"Desenvolvimento Militar Sentado com Barra","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Sente-se em um banco de desenvolvimento militar com a barra atrás da cabeça. Peça a um assistente para passar a barra (melhor para os ombros) ou segure-a com cuidado, com as palmas para frente e pegada mais larga que os ombros, formando um ângulo de 90 graus entre antebraço e braço quando a barra desce.","Com a barra na pegada correta, levante-a acima da cabeça até os braços ficarem estendidos. Segure na altura dos ombros e ligeiramente à frente da cabeça. Esta é a posição inicial.","Abaixe a barra lentamente até a altura da clavícula, inspirando.","Levante a barra de volta à posição inicial, expirando."],"tracking":"weight_reps"},{"id":"Dumbbell_Scaption","name":"Elevação Frontal com Halteres em 30 Graus","force":"push","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":["trapezio"],"category":"forca","instructions":["Este exercício corretivo fortalece os músculos que estabilizam a escápula. Segure um peso leve em cada mão, com os braços estendidos ao lado do corpo e os polegares apontando para cima.","Levante os braços à frente do corpo, formando um ângulo de aproximadamente 30 graus em relação à linha central, mantendo-os totalmente estendidos.","Continue até que os braços fiquem paralelos ao chão e, em seguida, retorne à posição inicial."],"tracking":"weight_reps"},{"id":"Bent_Over_Low-Pulley_Side_Lateral","name":"Elevação Lateral Inclinada com Polia Baixa","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["ombros"],"secondaryMuscles":["inferior-das-costas","meio-das-costas","trapezio"],"category":"forca","instructions":["Selecione o peso e segure a alça da polia baixa com a mão direita.","Incline-se na cintura até o tronco ficar quase paralelo ao chão, com os joelhos levemente flexionados e a mão esquerda apoiada na coxa esquerda. O braço direito deve estar pendurado com cotovelo levemente flexionado. Esta é a posição inicial.","Levante o braço direito lateralmente, com cotovelo flexionado, até ficar paralelo ao chão e alinhado com a orelha direita. Expire ao executar.","Abaixe o peso lentamente à posição inicial enquanto inspira."],"tracking":"weight_reps"},{"id":"Seated_Cable_Shoulder_Press","name":"Desenvolvimento de Ombros no Pulley Sentado","force":"push","level":"iniciante","mechanic":"composto","equipment":"cabo","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Ajuste o peso e sente-se, segurando as alças. Os braços devem estar a 90 graus do corpo, com a cabeça e o peito erguidos. Os cotovelos também a 90 graus. Esta é a posição inicial.","Estenda os cotovelos, pressionando as alças acima da cabeça.","Após uma pausa no topo, retorne as alças à posição inicial, mantendo a tensão nos cabos.","Pode-se fazer com as costas fora do encosto e alternando as mãos."],"tracking":"weight_reps"},{"id":"One-Arm_Kettlebell_Split_Jerk","name":"Arremesso em Afundo com Kettlebell de Um Braço","force":"push","level":"intermediario","mechanic":"composto","equipment":"kettlebell","primaryMuscles":["ombros"],"secondaryMuscles":["gluteos","isquiotibiais","quadriceps","triceps"],"category":"forca","instructions":["Segure o kettlebell pela alça e leve-o ao ombro com um movimento de arranco, estendendo as pernas e quadris enquanto puxa o peso em direção ao ombro. Gire o pulso para que a palma da mão fique virada para frente. Esta é a posição inicial.","Flexione os joelhos para abaixar o corpo, mantendo o tronco ereto.","Imediatamente inverta o movimento, empurrando pelos calcanhares como em um salto para gerar impulso. Ao fazer isso, pressione o kettlebell acima da cabeça até estender os braços.","Receba o peso acima da cabeça descendo para uma posição de afundo, com uma perna à frente e a outra atrás."],"tracking":"weight_reps"},{"id":"One-Arm_Kettlebell_Para_Press","name":"Desenvolvimento Para com Kettlebell de Um Braço","force":"push","level":"intermediario","mechanic":"composto","equipment":"kettlebell","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Leve o kettlebell ao ombro com um movimento de arranco, estendendo as pernas e quadris enquanto puxa o peso em direção ao ombro. Gire o pulso para que a palma da mão fique virada para frente. Esta é a posição inicial.","Segure o kettlebell com o cotovelo para o lado e pressione-o para cima e para fora até estender completamente o braço acima da cabeça.","Abaixe o kettlebell de volta ao ombro com controle e repita. Contraia o latíssimo, glúteos e abdômen com força para maior estabilidade e força."],"tracking":"weight_reps"},{"id":"Dumbbell_Lying_Rear_Lateral_Raise","name":"Elevação Lateral Posterior com Halteres Deitado","force":"pull","level":"intermediario","mechanic":"isolado","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":[],"category":"forca","instructions":["Segure um halter em cada mão e deite-se de bruços em um banco ajustável levemente inclinado (cerca de 15 graus em relação ao chão).","Mantenha os braços estendidos com os cotovelos levemente flexionados e as palmas das mãos voltadas para o torso. Esta é a posição inicial.","Eleve os braços para os lados até os cotovelos ficarem na altura dos ombros e os braços paralelos ao chão, expirando. Mantenha os braços perpendiculares ao torso e contraia por um segundo no topo.","Abaixe os halteres lentamente até a posição inicial, inspirando."],"tracking":"weight_reps"},{"id":"Standing_Barbell_Press_Behind_Neck","name":"Desenvolvimento com Barra Atrás do Pescoço em Pé","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Este exercício é melhor realizado dentro de um rack de agachamento para facilitar o levantamento da barra. Comece ajustando a barra em uma altura adequada. Com a barra carregada, posicione-se sob ela e apoie-a na parte de trás dos ombros (logo abaixo do pescoço).","Segure a barra com as duas mãos e levante-a do rack, empurrando com as pernas e endireitando o tronco.","Afaste-se do rack e posicione as pernas com uma postura na largura dos ombros, dedos ligeiramente para fora. Mantenha as costas retas. Esta é a posição inicial.","Eleve a barra sobre a cabeça, estendendo completamente os braços enquanto expira."],"tracking":"weight_reps"},{"id":"Leverage_Shoulder_Press","name":"Desenvolvimento de Ombros na Máquina de Alavanca","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Ajuste o peso e o banco para que as alças fiquem na altura dos ombros. Mantenha o peito erguido e segure as alças com pegada pronada. Esta é a posição inicial.","Empurre as alças para cima, estendendo os cotovelos.","Após uma breve pausa no topo, retorne o peso logo acima da posição inicial, mantendo a tensão muscular."],"tracking":"weight_reps"},{"id":"Front_Incline_Dumbbell_Raise","name":"Elevação Frontal com Halteres no Banco Inclinado","force":"push","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se em um banco inclinado entre 30 e 60 graus, segurando um halter em cada mão. Dica: Varie o ângulo para trabalhar o músculo de forma diferente.","Estenda os braços à frente, com as palmas voltadas para baixo e os halteres cerca de 2,5 cm acima das coxas. Esta é a posição inicial.","Levante os halteres lentamente até ficarem ligeiramente acima dos ombros, mantendo os cotovelos travados. Contraia no topo por um segundo e expire durante o movimento. Dica: Mantenha a cabeça apoiada no banco e os pés no chão.","Abaixe os braços de volta à posição inicial enquanto inspira."],"tracking":"weight_reps"},{"id":"Cable_Rope_Rear-Delt_Rows","name":"Remada Alta com Corda para Deltóides Posteriores","force":"pull","level":"iniciante","mechanic":"composto","equipment":"cabo","primaryMuscles":["ombros"],"secondaryMuscles":["biceps","meio-das-costas"],"category":"forca","instructions":["Sente-se em uma estação de remada baixa, como para remada sentada.","Conecte uma corda à polia e segure-a com uma pegada pronada. Os braços devem estar estendidos e paralelos ao chão, com os cotovelos abertos.","Mantenha a lombar ereta e recue os quadris, flexionando levemente os joelhos. Esta é a posição inicial.","Puxe a corda em direção ao peito, abaixo do pescoço, mantendo os cotovelos altos e para os lados. Expire até os cotovelos passarem levemente atrás das costas. Dica: Mantenha a parte superior dos braços horizontal."],"tracking":"weight_reps"},{"id":"Barbell_Rear_Delt_Row","name":"Remada Alta para Deltóides Posteriores com Barra","force":"pull","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["ombros"],"secondaryMuscles":["biceps","dorsais","meio-das-costas"],"category":"forca","instructions":["Fique em pé segurando uma barra com pegada larga (mais que a largura dos ombros) e pronada (palmas voltadas para o corpo).","Flexione levemente os joelhos e incline o tronco para frente, mantendo a curvatura natural das costas. Deixe os braços pendurados segurando a barra. Quando o tronco estiver paralelo ao chão, abra os cotovelos para os lados. Dica: O corpo deve formar um \"T\". Esta é a posição inicial.","Mantendo os braços superiores perpendiculares ao tronco, puxe a barra em direção ao peito superior, contraindo os deltóides posteriores e expirando. Dica: Foque nos deltóides; os braços devem agir como ganchos.","Retorne lentamente à posição inicial inspirando."],"tracking":"weight_reps"},{"id":"Standing_Palms-In_Dumbbell_Press","name":"Desenvolvimento com Halteres e Pegada Neutra em Pé","force":"push","level":"intermediario","mechanic":"composto","equipment":"halteres","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Comece com um halter em cada mão, com os braços totalmente estendidos para os lados usando uma pegada neutra. Os pés devem estar na largura dos ombros. Lentamente, levante os halteres até formar um ângulo de 90 graus com os braços. Nota: Os antebraços devem estar perpendiculares ao chão. Esta é a posição inicial.","Mantenha a pegada neutra durante todo o exercício. Lentamente, levante os halteres até os braços estarem totalmente estendidos.","Enquanto inspira, abaixe os pesos até os braços estarem novamente em um ângulo de 90 graus.","Repita para a quantidade recomendada de repetições."],"tracking":"weight_reps"},{"id":"Two-Arm_Kettlebell_Military_Press","name":"Desenvolvimento Militar com Kettlebell de Dois Braços","force":"push","level":"intermediario","mechanic":"composto","equipment":"kettlebell","primaryMuscles":["ombros"],"secondaryMuscles":["triceps"],"category":"forca","instructions":["Faça um clean com dois kettlebells até os ombros, girando os pulsos para que as palmas fiquem voltadas para frente.","Pressione os kettlebells para cima e para fora. Ao passarem da cabeça, incline-se para trás para apoiá-los atrás da nuca.","Contraia os dorsais, glúteos e abdômen para estabilidade."],"tracking":"weight_reps"},{"id":"One-Arm_Kettlebell_Push_Press","name":"Desenvolvimento com Impulso de Kettlebell de Um Braço","force":"push","level":"intermediario","mechanic":"composto","equipment":"kettlebell","primaryMuscles":["ombros"],"secondaryMuscles":["panturrilhas","quadriceps","triceps"],"category":"forca","instructions":["Segure o kettlebell pela alça e leve-o ao ombro com um movimento de arranco, estendendo as pernas e quadris enquanto puxa o peso em direção ao ombro. Gire o pulso para que a palma da mão fique virada para frente. Esta é a posição inicial.","Flexione os joelhos para abaixar o corpo, mantendo o tronco ereto.","Imediatamente inverta o movimento, empurrando pelos calcanhares como em um salto para gerar impulso. Ao fazer isso, pressione o kettlebell acima da cabeça até estender os braços, usando o momento do corpo para mover o peso. Abaixe o peso para a próxima repetição."],"tracking":"weight_reps"},{"id":"Calf_Press","name":"Press de Panturrilha","force":"push","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["panturrilhas"],"secondaryMuscles":[],"category":"forca","instructions":["Ajuste o assento para que as pernas fiquem levemente flexionadas na posição inicial. As pontas dos pés devem estar firmes na plataforma.","Selecione um peso adequado e segure as alças. Esta é a posição inicial.","Estenda os joelhos para levantar o peso, mantendo os tornozelos flexionados (dedos para cima). Pressione para baixo com as pontas dos pés o máximo possível.","Após uma breve pausa, retorne ao início e repita."],"tracking":"weight_reps"},{"id":"Seated_Calf_Raise","name":"Elevação de Panturrilha Sentada","force":"push","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["panturrilhas"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se na máquina e coloque a ponta dos pés na plataforma, com os calcanhares para fora. Escolha a posição dos pés (para frente, para dentro ou para fora).","Apoie as coxas sob a almofada da alavanca e ajuste-a conforme a altura. Segure a almofada para evitar que escorregue.","Levante a alavanca empurrando os calcanhares para cima e solte a trava de segurança. Esta é a posição inicial.","Abaixe os calcanhares flexionando os tornozelos até alongar totalmente as panturrilhas. Inspire."],"tracking":"weight_reps"},{"id":"Calf_Raise_On_A_Dumbbell","name":"Elevação de Panturrilha com Halter","force":"push","level":"intermediario","mechanic":"isolado","equipment":"halteres","primaryMuscles":["panturrilhas"],"secondaryMuscles":[],"category":"forca","instructions":["Segure-se em um objeto firme para equilíbrio e fique em cima do cabo de um halter, de preferência com placas redondas para aumentar a instabilidade.","Role o pé levemente para frente para alongar a panturrilha. Esta é a posição inicial.","Eleve a panturrilha rolando o pé sobre o cabo, estendendo-a completamente enquanto expira. Contraia a panturrilha no topo e segure por um segundo. Dica: Ao subir, role o halter levemente para trás.","Ao descer, inspire e role o halter para frente para um melhor alongamento."],"tracking":"weight_reps"},{"id":"Standing_Barbell_Calf_Raise","name":"Elevação de Panturrilha com Barra em Pé","force":"push","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["panturrilhas"],"secondaryMuscles":[],"category":"forca","instructions":["Este exercício é melhor realizado dentro de um rack de agachamento por segurança. Comece ajustando a barra em uma altura adequada. Com a barra carregada, posicione-se sob ela e apoie-a na parte de trás dos ombros (logo abaixo do pescoço).","Segure a barra com as duas mãos e levante-a do rack, empurrando com as pernas e endireitando o tronco.","Afaste-se do rack e posicione as pernas com uma postura na largura dos ombros, dedos ligeiramente para fora. Mantenha a cabeça erguida e as costas retas. Os joelhos devem ficar levemente flexionados, nunca travados. Esta é a posição inicial. Dica: Para maior amplitude, você pode colocar a ponta dos pés em um bloco, mas tome cuidado, pois isso exige mais equilíbrio.","Eleve os calcanhares, expirando, estendendo os tornozelos o máximo possível e contraindo a panturrilha. Mantenha os joelhos fixos, sem dobrá-los. Segure a contração por um segundo antes de descer."],"tracking":"weight_reps"},{"id":"Smith_Machine_Calf_Raise","name":"Elevação de Panturrilha no Smith Machine","force":"push","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["panturrilhas"],"secondaryMuscles":[],"category":"forca","instructions":["Coloque um bloco ou anilha abaixo da barra no Smith Machine. Ajuste a barra para uma altura que combine com sua estatura. Com a altura correta escolhida e a barra carregada, suba nas anilhas com a ponta dos pés e posicione a barra atrás dos ombros.","Segure a barra com as duas mãos voltadas para frente. Gire a barra para desengatá-la. Esta será sua posição inicial.","Eleve os calcanhares o mais alto possível, empurrando com a ponta dos pés e contraindo a panturrilha no topo do movimento. Mantenha os joelhos estendidos. Segure a posição contraída por um segundo antes de voltar.","Retorne lentamente à posição inicial enquanto inspira, abaixando os calcanhares."],"tracking":"weight_reps"},{"id":"Barbell_Seated_Calf_Raise","name":"Elevação de Panturrilha Sentado com Barra","force":"push","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["panturrilhas"],"secondaryMuscles":[],"category":"forca","instructions":["Coloque um bloco de cerca de 30 cm de altura na frente de um banco plano.","Sente-se no banco e apoie a ponta dos pés no bloco.","Peça para alguém colocar uma barra sobre suas coxas, cerca de 8 cm acima dos joelhos, e segure-a. Esta é a posição inicial.","Eleve os calcanhares o máximo possível, contraindo as panturrilhas e expirando."],"tracking":"weight_reps"},{"id":"Rocking_Standing_Calf_Raise","name":"Elevação de Panturrilha em Pé com Balanço","force":"push","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["panturrilhas"],"secondaryMuscles":[],"category":"forca","instructions":["Posicione-se em pé com os pés na largura dos ombros e os dedos ligeiramente apontados para fora. Mantenha a cabeça erguida e as costas retas, com os joelhos levemente flexionados.","Eleve os calcanhares ao expirar, estendendo os tornozelos o mais alto possível e contraindo a panturrilha. Mantenha os joelhos estáticos.","Segure a posição contraída por um segundo e retorne lentamente à posição inicial ao inspirar, abaixando os calcanhares.","Agora, levante os dedos dos pés ao expirar, contraindo os músculos da tíbia na frente da panturrilha."],"tracking":"weight_reps"},{"id":"Smith_Machine_Reverse_Calf_Raises","name":"Elevação de Panturrilha Invertida no Smith","force":"push","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["panturrilhas"],"secondaryMuscles":[],"category":"forca","instructions":["Ajuste a barra na máquina Smith para sua altura e posicione uma plataforma elevada logo abaixo dela.","Fique em pé na plataforma com os calcanhares apoiados nela e a parte da frente dos pés estendida para fora. Posicione os dedos dos pés para frente, com os pés na largura dos ombros.","Coloque os ombros sob a barra, mantendo a posição dos pés, e empurre a barra para cima estendendo os quadris e joelhos até ficar ereto. Mantenha os joelhos levemente flexionados, nunca travados. Esta é a posição inicial. Dica: A barra nas costas é apenas para equilíbrio.","Eleve a parte da frente dos pés enquanto expira, estendendo os dedos o mais alto possível e contraindo a panturrilha. Mantenha os joelhos imóveis, sem dobrá-los. Segure a posição contraída por um segundo antes de voltar."],"tracking":"weight_reps"},{"id":"Dumbbell_Seated_One-Leg_Calf_Raise","name":"Panturrilha Sentado com Uma Perna e Halteres","force":"push","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["panturrilhas"],"secondaryMuscles":[],"category":"forca","instructions":["Coloque um bloco no chão a cerca de 30 cm de um banco plano.","Sente-se no banco e apoie um halter na parte superior da coxa esquerda, cerca de 8 cm acima do joelho.","Posicione a ponta do pé esquerdo no bloco. Esta será sua posição inicial.","Eleve os dedos do pé o mais alto possível, expirando e contraindo a panturrilha. Mantenha a contração por um segundo."],"tracking":"weight_reps"},{"id":"Calf_Press_On_The_Leg_Press_Machine","name":"Press de Panturrilha na Máquina de Leg Press","force":"push","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["panturrilhas"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se na máquina de leg press e coloque os pés na plataforma com uma postura média (largura dos ombros).","Libere as travas de segurança e empurre a plataforma até as pernas ficarem quase estendidas, sem travar os joelhos. Posicione as pontas dos pés na parte inferior da plataforma, com os calcanhares para fora. Esta é a posição inicial.","Eleve os calcanhares enquanto expira, estendendo os tornozelos ao máximo e contraindo a panturrilha. Mantenha os joelhos imóveis. Segure a contração por um segundo.","Abaixe os calcanhares lentamente enquanto inspira, alongando as panturrilhas."],"tracking":"weight_reps"},{"id":"Butterfly","name":"Butterfly","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["peito"],"secondaryMuscles":[],"category":"forca","instructions":["Sente-se na máquina com as costas retas no encosto.","Segure as alças. Dica: os braços superiores devem estar paralelos ao chão; ajuste a máquina conforme necessário. Esta é a posição inicial.","Empurre as alças juntas lentamente enquanto contrai o peito no meio. Expire durante esta parte do movimento e segure a contração por um segundo.","Volte à posição inicial lentamente enquanto inspira, até que os músculos do peito estejam totalmente alongados."],"tracking":"weight_reps"},{"id":"Machine_Bench_Press","name":"Supino Máquina","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Sente-se na Máquina de Supino e selecione o peso.","Pise na alavanca da máquina para trazer as alças para frente, segure-as e estenda os braços completamente.","Segure as alças com pegada pronada e levante os cotovelos até que os braços superiores fiquem paralelos ao chão, ao lado do torso. Dica: Antebraços apontando para frente; ao estender os braços, estará na posição inicial.","Trague as alças em sua direção, inspirando."],"tracking":"weight_reps"},{"id":"Incline_Push-Up","name":"Flexão Inclinada","force":"push","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Fique de frente para um banco ou plataforma elevada. Coloque as mãos na borda, ligeiramente mais afastadas que a largura dos ombros.","Posicione os pés afastados do banco, com braços e corpo retos. Os braços devem estar perpendiculares ao corpo. Mantenha o corpo reto e abaixe o peito até a borda dobrando os braços.","Empurre o corpo para cima até estender os braços. Repita."],"tracking":"reps"},{"id":"Cable_Crossover","name":"Crossover na Polia","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["peito"],"secondaryMuscles":["ombros"],"category":"forca","instructions":["Posicione as polias na parte alta (acima da cabeça), selecione a resistência e segure as alças com cada mão.","Dê um passo à frente, mantendo o tronco levemente inclinado para a frente, e junte os braços à sua frente. Esta é a posição inicial.","Com os cotovelos levemente flexionados, abra os braços lateralmente em um arco amplo até sentir o peitoral alongar, inspirando.","Retorne os braços à posição inicial expirando, seguindo o mesmo arco de movimento."],"tracking":"weight_reps"},{"id":"Dumbbell_Bench_Press","name":"Supino com Halteres","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Deite-se em um banco plano com um halter em cada mão apoiado sobre as coxas. As palmas das mãos devem estar voltadas uma para a outra.","Use as coxas para ajudar a levantar os halteres, erguendo-os um de cada vez até segurá-los na frente de você na largura dos ombros.","Na largura dos ombros, gire os pulsos para frente, de modo que as palmas fiquem voltadas para longe de você. Os halteres devem ficar ao lado do peito, com o braço superior e o antebraço formando um ângulo de 90 graus. Mantenha o controle total dos halteres. Esta será a posição inicial.","Ao expirar, use o peito para empurrar os halteres para cima. Trave os braços no topo do movimento e contraia o peito, segure por um segundo e depois desça lentamente. Dica: Idealmente, baixar o peso deve levar o dobro do tempo que levantá-lo."],"tracking":"weight_reps"},{"id":"Dumbbell_Flyes","name":"Crucifixo com Halteres","force":"push","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["peito"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se em um banco plano com um halter em cada mão apoiado sobre as coxas. As palmas das mãos devem estar voltadas uma para a outra.","Use as coxas para ajudar a levantar os halteres, erguendo-os um de cada vez até segurá-los na frente de você na largura dos ombros, com as palmas se enfrentando. Levante os halteres como se fosse fazer um supino, mas pare e segure logo antes de travar os braços. Esta será a posição inicial.","Com uma leve flexão nos cotovelos para evitar estresse no tendão do bíceps, abaixe os braços para os lados em um arco amplo até sentir um alongamento no peito. Inspire ao realizar essa parte do movimento. Dica: Lembre-se de que os braços devem permanecer estáticos; o movimento deve ocorrer apenas na articulação do ombro.","Volte os braços à posição inicial enquanto contrai os músculos do peito e expira. Dica: Use o mesmo arco de movimento usado para baixar os pesos."],"tracking":"weight_reps"},{"id":"Push-Up_Wide","name":"Flexão com Apoio Ampla","force":null,"level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["peito"],"secondaryMuscles":["abdominais","ombros","triceps"],"category":"forca","instructions":["Com as mãos bem afastadas, apoie o corpo na ponta dos pés e nas mãos em posição de prancha. Mantenha os cotovelos estendidos e o corpo reto, sem deixar os quadris caírem. Esta é a posição inicial.","Inspire e flexione os cotovelos, abaixando o peito em direção ao chão.","Use os músculos peitorais para empurrar o corpo de volta à posição inicial, estendendo os cotovelos. Expire durante esse movimento.","Após uma pausa na posição contraída, repita o movimento pelo número de repetições prescrito."],"tracking":"reps"},{"id":"Push-Ups_With_Feet_Elevated","name":"Flexão com Pés Elevados","force":"push","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Deite-se de bruços no chão com as mãos afastadas cerca de 90 cm e o torso sustentado pelos braços estendidos.","Apoie a ponta dos pés em um banco plano para elevar o corpo. Observação: quanto mais alto o banco, maior a resistência.","Inspire e abaixe-se até o peito quase tocar o chão.","Use os músculos peitorais para empurrar o corpo de volta à posição inicial, contraindo o peito. Expire durante o movimento."],"tracking":"reps"},{"id":"Smith_Machine_Bench_Press","name":"Supino no Smith Machine","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Posicione um banco reto sob o Smith machine. Ajuste a barra a uma altura que você possa alcançar deitado, com os braços quase totalmente estendidos. Após selecionar o peso, deite-se no banco reto. Com uma pegada pronada mais larga que os ombros, solte a barra do suporte e segure-a reta acima de você, com os braços travados. Esta é a posição inicial.","Ao inspirar, desça a barra lentamente até sentir que ela toca o meio do peito.","Após uma pausa de um segundo, retorne a barra à posição inicial ao expirar, empurrando com os músculos do peito. Trave os braços na posição contraída, segure por um segundo e comece a descer lentamente novamente. Dica: O movimento de descida deve levar pelo menos o dobro do tempo da subida.","Repita o movimento pelo número de repetições prescrito."],"tracking":"weight_reps"},{"id":"Low_Cable_Crossover","name":"Crossover na Polia Baixa","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["peito"],"secondaryMuscles":["ombros"],"category":"forca","instructions":["Para a posição inicial, ajuste as polias na posição baixa, selecione a resistência e segure uma alça em cada mão.","Dê um passo à frente para criar tensão nas polias. As palmas devem estar voltadas para frente, as mãos abaixo da cintura e os braços retos. Esta será a posição inicial.","Com uma leve flexão nos braços, puxe as mãos para cima e em direção à linha média do corpo. As mãos devem se encontrar na frente do peito, com as palmas para cima.","Retorne os braços à posição inicial após uma breve pausa."],"tracking":"weight_reps"},{"id":"Decline_Barbell_Bench_Press","name":"Supino Declinado com Barra","force":"push","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Prenda as pernas na extremidade do banco declinado e deite-se lentamente.","Com uma pegada média (que forme um ângulo de 90 graus no meio do movimento), levante a barra do rack e segure-a acima de você com os braços travados e perpendiculares ao chão. Esta é a posição inicial. Dica: Para proteger o manguito rotador, peça ajuda a um parceiro para retirar a barra.","Inspire e desça a barra lentamente até sentir no peito inferior.","Após uma pausa breve, retorne à posição inicial expirando e usando os músculos peitorais. Trave os braços e contraia o peito no topo, segure por um segundo e desça novamente. Dica: A descida deve ser pelo menos duas vezes mais lenta que a subida."],"tracking":"weight_reps"},{"id":"Front_Raise_And_Pullover","name":"Elevação Frontal e Pullover","force":"pull","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["peito"],"secondaryMuscles":["dorsais","ombros","triceps"],"category":"forca","instructions":["Deite-se em um banco reto, segurando uma barra com as palmas para baixo e as mãos afastadas cerca de 40 cm.","Apoie a barra nas coxas, com os braços estendidos e cotovelos ligeiramente flexionados. Esta é a posição inicial.","Levante a barra em um movimento semicircular, mantendo os braços retos, enquanto inspira. Continue até a barra ficar acima da cabeça, com os braços paralelos ao chão e palmas para cima.","Retorne a barra à posição inicial revertendo o movimento enquanto expira."],"tracking":"weight_reps"},{"id":"Push_Up_to_Side_Plank","name":"Flexão para Prancha Lateral","force":"push","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["peito"],"secondaryMuscles":["abdominais","ombros","triceps"],"category":"forca","instructions":["Posicione-se em flexão de braço, com as mãos levemente além da largura dos ombros e apoiado na ponta dos pés.","Faça uma flexão, flexionando os cotovelos e mantendo o corpo reto ao descer.","Ao subir, transfira o peso para o lado esquerdo, gire o corpo e eleve o braço direito em direção ao teto, formando uma prancha lateral.","Volte o braço ao chão para outra flexão e repita para o outro lado."],"tracking":"reps"},{"id":"Decline_Dumbbell_Bench_Press","name":"Supino Declinado com Halteres","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Prenda as pernas na extremidade do banco declinado e deite-se com um halter em cada mão sobre as coxas, palmas voltadas uma para a outra.","Ao deitar, posicione os halteres à frente na largura dos ombros.","Gire os pulsos para frente, com as palmas voltadas para longe de você. Esta é a posição inicial.","Desça os pesos lentamente para os lados, expirando e mantendo o controle. Dica: Os antebraços devem permanecer perpendiculares ao chão."],"tracking":"weight_reps"},{"id":"Incline_Dumbbell_Press","name":"Supino Inclinado com Halteres","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Deite-se em um banco inclinado com um haltere em cada mão apoiado sobre as coxas, palmas voltadas uma para a outra.","Use as coxas para ajudar a levantar os halteres um de cada vez até a altura dos ombros, com as mãos na largura dos ombros.","Gire os punhos para frente até as palmas ficarem voltadas para longe de você. Esta é a posição inicial. Mantenha o controle dos halteres.","Expire e empurre os halteres para cima usando o peito."],"tracking":"weight_reps"},{"id":"Leverage_Chest_Press","name":"Supino na Máquina de Alavanca","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Ajuste o peso nos pinos e o banco para que as alças fiquem na altura do peito. Mantenha o peito erguido e as escápulas retraídas. Esta é a posição inicial.","Empurre as alças para frente, estendendo os cotovelos.","Após uma breve pausa no topo, retorne o peso logo acima da posição inicial, mantendo a tensão muscular."],"tracking":"weight_reps"},{"id":"Cross_Over_-_With_Bands","name":"Crossover com Faixas Elásticas","force":"push","level":"iniciante","mechanic":"composto","equipment":"faixas","primaryMuscles":["peito"],"secondaryMuscles":["biceps","ombros"],"category":"forca","instructions":["Prenda uma faixa elástica em um ponto fixo.","De costas para o ponto, segure as alças da faixa e afaste-se para criar tensão.","Eleve os braços para os lados, paralelos ao chão, com uma leve flexão nos cotovelos e palmas para frente, formando um \"T\" com o torso. Esta é a posição inicial.","Mantendo os braços retos, traga-os para a frente em um movimento semicircular, expirando e contraindo o peitoral. Segure a contração por um segundo."],"tracking":"weight_reps"},{"id":"Decline_Dumbbell_Flyes","name":"Crucifixo Declinado com Halteres","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["peito"],"secondaryMuscles":[],"category":"forca","instructions":["Prenda as pernas na extremidade do banco declinado e deite-se com um halter em cada mão sobre as coxas, palmas voltadas uma para a outra.","Ao deitar, posicione os halteres à frente na largura dos ombros, com os braços estendidos e perpendiculares ao chão. Esta é a posição inicial.","Com uma ligeira flexão nos cotovelos para evitar estresse, abaixe os braços em um arco amplo até sentir o alongamento no peito, inspirando. Dica: Movimente apenas os ombros.","Retorne os braços à posição inicial contraindo os peitorais e expirando. Dica: Use o mesmo arco de movimento."],"tracking":"weight_reps"},{"id":"Incline_Dumbbell_Flyes","name":"Crucifixo Inclinado com Halteres","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["peito"],"secondaryMuscles":["ombros"],"category":"forca","instructions":["Segure um haltere em cada mão e deite-se em um banco inclinado com ângulo máximo de 30 graus.","Estenda os braços acima de você com uma leve flexão nos cotovelos.","Gire os punhos até as palmas das mãos ficarem voltadas para você, com os dedos mindinhos próximos um do outro. Esta é a posição inicial.","Inspire e abaixe os braços lateralmente, mantendo-os estendidos e girando os punhos até as palmas se enfrentarem. Ao final, os braços estarão ao lado do corpo com as palmas para cima."],"tracking":"weight_reps"},{"id":"Flat_Bench_Cable_Flyes","name":"Crucifixo no Cabo com Banco Plano","force":"push","level":"intermediario","mechanic":"isolado","equipment":"cabo","primaryMuscles":["peito"],"secondaryMuscles":[],"category":"forca","instructions":["Posicione um banco plano entre duas polias baixas, de modo que, ao deitar, seu peito fique alinhado com as polias.","Deite-se de costas no banco com os pés no chão.","Pegue as alças com as palmas voltadas para cima, mantendo os braços estendidos ao lado do corpo com uma leve flexão nos cotovelos. Esta é a posição inicial.","Levante os braços em um movimento semicircular à sua frente, juntando as mãos no topo. Contraia o peito, expire e segure a contração por um segundo."],"tracking":"weight_reps"},{"id":"Incline_Push-Up_Wide","name":"Flexão Inclinada com Pegada Larga","force":"push","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["peito"],"secondaryMuscles":["abdominais","ombros","triceps"],"category":"forca","instructions":["Fique de frente para a barra de um Smith machine ou uma plataforma elevada firme na altura adequada.","Coloque as mãos na barra, mais afastadas que a largura dos ombros.","Posicione os pés atrás da barra, com os braços e o corpo retos. Os braços devem estar perpendiculares ao corpo. Esta será a posição inicial.","Mantendo o corpo reto, abaixe o peito em direção à barra flexionando os braços."],"tracking":"reps"},{"id":"Incline_Push-Up_Medium","name":"Flexão Inclinada com Pegada Média","force":"push","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["peito"],"secondaryMuscles":["abdominais","ombros","triceps"],"category":"forca","instructions":["Fique de frente para a barra de um Smith machine ou plataforma elevada na altura adequada.","Coloque as mãos na barra com afastamento igual à largura dos ombros.","Posicione os pés afastados da barra, com braços e corpo retos. Esta é a posição inicial.","Mantendo o corpo reto, abaixe o peito até a barra dobrando os braços."],"tracking":"reps"},{"id":"Smith_Machine_Decline_Press","name":"Supino Declinado no Smith Machine","force":null,"level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Posicione um banco declinado no rack para que a barra fique acima do peito. Carregue o peso adequado e deite-se no banco.","Gire a barra para desengatá-la e estenda totalmente os braços. Mantenha as costas levemente arqueadas e as escápulas retraídas. Esta é a posição inicial.","Inicie o movimento flexionando os braços, abaixando a barra até o peito.","Faça uma pausa breve e estenda os braços para empurrar o peso de volta à posição inicial."],"tracking":"weight_reps"},{"id":"Smith_Machine_Incline_Bench_Press","name":"Supino Inclinado no Smith Machine","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Posicione um banco inclinado sob o Smith Machine. Ajuste a barra para uma altura que você alcance deitado com os braços quase totalmente estendidos. Com o peso selecionado, deite-se no banco inclinado, alinhando a parte superior do peito com a barra. Use uma pegada pronada (palmas para frente) mais larga que os ombros, desengate a barra e segure-a reta acima de você com os braços travados. Esta é a posição inicial.","Inspire e desça lentamente até a barra tocar a parte superior do peito.","Após uma pausa de um segundo, retorne a barra à posição inicial enquanto expira, empurrando com os músculos do peito. Trave os braços na posição contraída, segure por um segundo e desça novamente. Dica: A descida deve ser pelo menos duas vezes mais lenta que a subida.","Repita o movimento pelo número prescrito de repetições."],"tracking":"weight_reps"},{"id":"Straight-Arm_Dumbbell_Pullover","name":"Pullover com Halteres Braços Retos","force":"pull","level":"intermediario","mechanic":"composto","equipment":"halteres","primaryMuscles":["peito"],"secondaryMuscles":["dorsais","ombros","triceps"],"category":"forca","instructions":["Coloque um haltere em pé em um banco plano.","Deite-se perpendicular ao banco, com os ombros apoiados, quadris abaixo do banco e pés no chão. A cabeça ficará fora do banco.","Segure o haltere com as duas mãos, braços estendidos acima do peito, com as palmas pressionando a parte inferior do haltere. Esta é a posição inicial. Cuidado: use um haltere seguro para evitar acidentes.","Mantendo os braços retos, abaixe o peso em um arco atrás da cabeça, inspirando, até sentir um alongamento no peito."],"tracking":"weight_reps"},{"id":"Dumbbell_Bench_Press_with_Neutral_Grip","name":"Supino com Halteres e Pegada Neutra","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Segure um halter em cada mão e deite-se em um banco plano. Os pés devem estar apoiados no chão e as escápulas retraídas.","Mantendo uma pegada neutra (palmas voltadas uma para a outra), comece com os braços estendidos diretamente acima de você, perpendicular ao chão. Esta será a posição inicial.","Inicie o movimento flexionando os cotovelos, baixando os braços superiores para os lados. Desça até os halteres chegarem perto do torso.","Faça uma pausa e, em seguida, estenda os cotovelos para voltar à posição inicial."],"tracking":"weight_reps"},{"id":"Decline_Smith_Press","name":"Supino no Smith com Banco Declinado","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Posicione um banco declinado sob o Smith machine. Ajuste a barra para que você alcance com os braços quase estendidos ao deitar. Use uma pegada pronada mais larga que os ombros, destrave a barra e segure-a reta acima. Esta é a posição inicial.","Inspire e abaixe a barra com controle, flexionando os cotovelos até tocar levemente o torso.","Após uma pausa breve, retorne a barra à posição inicial estendendo os cotovelos, expirando.","Repita o movimento para as repetições prescritas."],"tracking":"weight_reps"},{"id":"Barbell_Bench_Press_-_Medium_Grip","name":"Supino Reto com Barra - Pegada Média","force":"push","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Deite-se em um banco reto. Com uma pegada média (que forme um ângulo de 90 graus no meio do movimento), levante a barra do rack e segure-a acima de você com os braços travados. Esta será sua posição inicial.","Da posição inicial, inspire e desça lentamente até a barra tocar o meio do seu peito.","Após uma breve pausa, empurre a barra de volta à posição inicial enquanto expira, focando nos músculos do peito. Trave os braços e contraia o peito no topo, segure por um segundo e desça novamente.","Repita pelo número prescrito de repetições."],"tracking":"weight_reps"},{"id":"Wide-Grip_Barbell_Bench_Press","name":"Supino Reto com Barra e Pegada Larga","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Deite-se em um banco plano com os pés firmes no chão. Segure a barra com uma pegada pronada e larga (cerca de 3 polegadas além da largura dos ombros), levantando-a do suporte e mantendo os braços travados acima do peito. Esta é a posição inicial.","Inspire e desça a barra lentamente até tocar o meio do peito.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial, expirando e contraindo o peito. Trave os braços e segure a contração por um segundo antes de descer novamente. Dica: A descida deve ser pelo menos duas vezes mais lenta que a subida.","Repita o movimento para o número de repetições prescrito."],"tracking":"weight_reps"},{"id":"Incline_Push-Up_Reverse_Grip","name":"Flexão Inclinada com Pegada Invertida","force":"push","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["peito"],"secondaryMuscles":["abdominais","ombros","triceps"],"category":"forca","instructions":["Fique de frente para a barra de um Smith machine ou uma plataforma elevada firme na altura adequada.","Coloque as mãos na barra com as palmas para cima, afastadas na largura dos ombros.","Posicione os pés atrás da barra, com os braços e o corpo retos. Esta será a posição inicial.","Mantendo o corpo reto, abaixe o peito em direção à barra flexionando os braços."],"tracking":"reps"},{"id":"Leverage_Decline_Chest_Press","name":"Supino Declinado na Máquina de Alavanca","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Ajuste o peso e o banco declinado para que as alças fiquem na parte inferior do peito. Mantenha o peito erguido e as escápulas retraídas. Esta é a posição inicial.","Empurre as alças para frente, estendendo os cotovelos.","Após uma breve pausa no topo, retorne o peso logo acima da posição inicial, mantendo a tensão muscular."],"tracking":"weight_reps"},{"id":"Leverage_Incline_Chest_Press","name":"Supino Inclinado na Máquina de Alavanca","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Ajuste o peso e o banco inclinado para que as alças fiquem na parte superior do peito. Mantenha o peito erguido e as escápulas retraídas. Esta é a posição inicial.","Empurre as alças para frente, estendendo os cotovelos.","Após uma breve pausa no topo, retorne o peso logo acima da posição inicial, mantendo a tensão muscular."],"tracking":"weight_reps"},{"id":"Bent-Arm_Dumbbell_Pullover","name":"Pullover com Halter e Braços Flexionados","force":"push","level":"intermediario","mechanic":"composto","equipment":"halteres","primaryMuscles":["peito"],"secondaryMuscles":["dorsais","ombros","triceps"],"category":"forca","instructions":["Coloque um halter em pé em um banco plano.","Certifique-se de que o halter esteja seguro, deite-se perpendicular ao banco, com apenas os ombros apoiados. Os quadris devem ficar abaixo do banco, pernas flexionadas e pés firmes no chão. A cabeça ficará fora do banco.","Segure o halter com as duas mãos, mantendo-o reto sobre o peito com os braços flexionados. Ambas as palmas devem pressionar a parte inferior do halter. Esta será a posição inicial. Cuidado: Use sempre um halter seguro para evitar acidentes.","Mantendo os braços flexionados, abaixe o peso lentamente em um arco atrás da cabeça, inspirando, até sentir um alongamento no peito."],"tracking":"weight_reps"},{"id":"Wide-Grip_Decline_Barbell_Bench_Press","name":"Supino Declinado com Barra e Pegada Larga","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Deite-se em um banco declinado com os pés firmemente travados. Segure a barra com uma pegada pronada e larga (cerca de 3 polegadas além da largura dos ombros), levantando-a do suporte e mantendo os braços travados acima do peito. Esta é a posição inicial.","Inspire e desça a barra lentamente até tocar a parte inferior do peito.","Após uma pausa de um segundo, empurre a barra de volta à posição inicial, expirando e contraindo o peito. Trave os braços e segure a contração por um segundo antes de descer novamente. Dica: A descida deve ser pelo menos duas vezes mais lenta que a subida.","Repita o movimento para o número de repetições prescrito."],"tracking":"weight_reps"},{"id":"Barbell_Incline_Bench_Press_-_Medium_Grip","name":"Supino Inclinado com Barra - Pegada Média","force":"push","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Deite-se em um banco inclinado. Com uma pegada média (que forme um ângulo de 90 graus no meio do movimento), levante a barra do suporte e segure-a acima de você com os braços travados. Esta é a posição inicial.","Inspire e desça a barra lentamente até tocar o peito superior.","Após uma pausa de um segundo, retorne à posição inicial expirando e usando os músculos do peito. Trave os braços, contraia o peito, segure por um segundo e desça novamente. Dica: A descida deve ser pelo menos duas vezes mais lenta que a subida.","Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Hammer_Grip_Incline_DB_Bench_Press","name":"Supino Inclinado com Halteres em Pegada Neutra","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Deite-se em um banco inclinado com um halter em cada mão apoiado sobre as coxas. As palmas das mãos devem estar voltadas uma para a outra.","Use as coxas para ajudar a levantar os halteres, limpando-os um de cada vez até segurá-los na largura dos ombros.","Com os halteres na altura dos ombros, mantenha as palmas com uma pegada neutra (voltadas uma para a outra). Mantenha os cotovelos abertos, com os braços superiores alinhados com os ombros (perpendiculares ao torso) e os cotovelos dobrados em um ângulo de 90 graus. Esta será sua posição inicial.","Abaixe os pesos lentamente para os lados enquanto inspira. Mantenha o controle total dos halteres o tempo todo."],"tracking":"weight_reps"},{"id":"Wide-Grip_Decline_Barbell_Pullover","name":"Pullover com Barra em Banco Declinado e Pegada Larga","force":"pull","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["peito"],"secondaryMuscles":["ombros","triceps"],"category":"forca","instructions":["Deite-se em um banco declinado com as pernas travadas. Segure a barra atrás da cabeça com uma pegada pronada e mais larga que os ombros, levantando-a até que os braços fiquem estendidos e perpendiculares ao chão. Esta é a posição inicial.","Movimente a barra para trás em um arco semicircular, mantendo os braços estendidos, até que fiquem paralelos ao chão. Inspire durante esse movimento.","Traga a barra de volta à posição inicial, expirando e mantendo o controle total.","Repita para o número de repetições prescrito."],"tracking":"weight_reps"},{"id":"Leg_Press","name":"Leg Press","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Sente-se na máquina de leg press e posicione os pés na plataforma à sua frente, com uma postura média (largura dos ombros).","Abra as travas de segurança e empurre a plataforma até as pernas ficarem quase totalmente estendidas, sem travar os joelhos. O tronco e as pernas devem formar um ângulo de 90 graus. Esta é a posição inicial.","Inspire e abaixe lentamente a plataforma até as coxas e panturrilhas formarem um ângulo de 90 graus.","Empurre principalmente com os calcanhares, usando os quadríceps, para voltar à posição inicial enquanto expira."],"tracking":"weight_reps"},{"id":"Barbell_Lunge","name":"Afundo com Barra","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Para segurança, execute este exercício dentro de um rack de agachamento. Ajuste a barra logo abaixo da altura dos ombros. Após carregar a barra, posicione-se sob ela, apoiando-a nas costas dos ombros.","Segure a barra com as duas mãos e levante-a do rack empurrando com as pernas e endireitando o tronco.","Afaste-se do rack e dê um passo à frente com a perna direita, agachando pelos quadris, mantendo o tronco ereto e o equilíbrio. Inspire ao descer. Dica: Não deixe o joelho ultrapassar a ponta dos pés.","Empurre com o calcanhar para retornar à posição inicial, expirando."],"tracking":"weight_reps"},{"id":"Hack_Squat","name":"Agachamento Hack","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Apoie as costas no encosto da máquina e encaixe os ombros sob as almofadas fornecidas.","Posicione as pernas na plataforma com uma postura de largura média dos ombros e os pés ligeiramente apontados para fora. Dica: Mantenha a cabeça erguida e as costas sempre apoiadas no encosto.","Coloque os braços nas alças laterais da máquina e desengate as travas de segurança (geralmente feito girando as alças de uma posição frontal para diagonal).","Estenda as pernas sem travar os joelhos. Esta será sua posição inicial."],"tracking":"weight_reps"},{"id":"Barbell_Step_Ups","name":"Step Up com Barra","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais","quadriceps"],"category":"forca","instructions":["Fique em pé, segurando uma barra apoiada nas costas dos ombros (ligeiramente abaixo do pescoço), e posicione-se atrás de uma plataforma elevada (como um step). Esta é a posição inicial.","Coloque o pé direito na plataforma. Suba na plataforma estendendo o quadril e o joelho da perna direita. Use principalmente o calcanhar para levantar o corpo e coloque o pé esquerdo na plataforma também. Expire enquanto executa o movimento de subida.","Desça com a perna esquerda, flexionando o quadril e o joelho da perna direita, enquanto inspira. Retorne à posição inicial colocando o pé direito ao lado do esquerdo.","Repita com a perna direita para a quantidade recomendada de repetições e depois faça com a perna esquerda."],"tracking":"weight_reps"},{"id":"Goblet_Squat","name":"Agachamento Goblet","force":"push","level":"iniciante","mechanic":"composto","equipment":"kettlebell","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais","ombros"],"category":"forca","instructions":["Fique em pé segurando um kettlebell leve pelos chifres próximo ao peito. Esta será sua posição inicial.","Agache-se entre as pernas até que os isquiotibiais toquem as panturrilhas. Mantenha o peito e a cabeça erguidos e as costas retas.","Na posição mais baixa, faça uma pausa e use os cotovelos para empurrar os joelhos para fora. Retorne à posição inicial e repita por 10 a 20 repetições."],"tracking":"weight_reps"},{"id":"Leg_Extensions","name":"Extensão de Pernas","force":"push","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"category":"forca","instructions":["Para este exercício, você precisará usar uma máquina de extensão de pernas. Primeiro, escolha seu peso e sente-se na máquina com as pernas sob a almofada (pés apontados para frente) e as mãos segurando as barras laterais. Esta será sua posição inicial. Dica: Ajuste a almofada para que fique sobre a parte inferior da perna (logo acima dos pés). Além disso, certifique-se de que as pernas formem um ângulo de 90 graus entre a parte inferior e superior. Se o ângulo for menor que 90 graus, isso significa que o joelho está sobre os dedos, o que cria estresse indevido na articulação do joelho. Se a máquina for assim, procure outra ou apenas certifique-se de parar de descer quando atingir o ângulo de 90 graus.","Usando os quadríceps, estenda as pernas ao máximo enquanto expira. Certifique-se de que o resto do corpo permaneça parado no assento. Faça uma pausa de um segundo na posição contraída.","Lentamente, abaixe o peso de volta à posição original enquanto inspira, garantindo que não ultrapasse o limite de 90 graus.","Repita para o número recomendado de vezes."],"tracking":"weight_reps"},{"id":"Dumbbell_Lunges","name":"Afundo com Halteres","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Fique em pé com o tronco ereto, segurando dois halteres nas mãos ao lado do corpo. Esta será a posição inicial.","Dê um passo à frente com a perna direita, cerca de 60 cm da perna esquerda estacionária atrás, e abaixe o tronco, mantendo-o ereto e o equilíbrio. Inspire ao descer. Nota: Não permita que o joelho da frente ultrapasse a linha dos dedos dos pés ao descer, para evitar estresse excessivo na articulação. Mantenha a canela da perna da frente perpendicular ao chão.","Usando principalmente o calcanhar do pé, empurre para cima e volte à posição inicial enquanto expira.","Repita o movimento pelo número recomendado de repetições e, em seguida, execute com a perna esquerda."],"tracking":"weight_reps"},{"id":"Bodyweight_Squat","name":"Agachamento Corporal","force":"push","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["quadriceps"],"secondaryMuscles":["gluteos","isquiotibiais"],"category":"forca","instructions":["Fique em pé com os pés na largura dos ombros, mãos atrás da cabeça. Esta é a posição inicial.","Flexione joelhos e quadris, sentando para trás com os quadris.","Desça até a amplitude completa, se possível, e reverta rapidamente o movimento para retornar à posição inicial. Mantenha o peito erguido e os joelhos para fora durante o agachamento."],"tracking":"reps"},{"id":"Smith_Machine_Squat","name":"Agachamento no Smith","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais","inferior-das-costas"],"category":"forca","instructions":["Ajuste a barra na máquina Smith para sua altura. Com a barra carregada, posicione-se sob ela, apoiando-a nas costas dos ombros (logo abaixo do pescoço).","Segure a barra com as duas mãos nas laterais (palmas para frente), destrave-a e levante-a do suporte empurrando com as pernas e endireitando o tronco.","Posicione as pernas com os pés na largura dos ombros e dedos levemente para fora. Mantenha a cabeça erguida e as costas retas. Esta é a posição inicial.","Abaixe a barra lentamente dobrando os joelhos, mantendo a postura reta e a cabeça erguida. Desça até as coxas ficarem abaixo do paralelo com o chão (ângulo menor que 90 graus). Inspire durante esse movimento. Dica: Os joelhos não devem passar a linha dos dedos dos pés."],"tracking":"weight_reps"},{"id":"Dumbbell_Step_Ups","name":"Step Up com Halteres","force":"push","level":"intermediario","mechanic":"composto","equipment":"halteres","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Fique em pé segurando um halter em cada mão (palmas voltadas para as pernas).","Coloque o pé direito em uma plataforma elevada. Suba estendendo o quadril e o joelho da perna direita, usando principalmente o calcanhar. Expire ao subir e coloque o pé esquerdo na plataforma.","Desça com a perna esquerda, flexionando o quadril e joelho da perna direita, inspirando. Retorne à posição inicial.","Repita com a perna direita para o número de repetições prescrito e depois faça com a perna esquerda."],"tracking":"weight_reps"},{"id":"Barbell_Squat","name":"Agachamento com Barra","force":"push","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais","inferior-das-costas"],"category":"forca","instructions":["Este exercício é melhor realizado dentro de um rack de agachamento por segurança. Para começar, ajuste a barra no rack logo abaixo da altura dos ombros. Com a altura correta escolhida e a barra carregada, posicione-se sob a barra e apoie-a nas costas dos ombros (ligeiramente abaixo do pescoço).","Segure a barra com ambas as mãos nas laterais e levante-a do rack empurrando com as pernas e endireitando o tronco ao mesmo tempo.","Afaste-se do rack e posicione as pernas com uma postura média na largura dos ombros, com os pés levemente virados para fora. Mantenha a cabeça erguida e as costas retas. Esta será a posição inicial.","Comece a abaixar a barra lentamente, flexionando os joelhos e os quadris, mantendo a postura reta e a cabeça erguida. Continue descendo até que o ângulo entre a coxa e a panturrilha fique ligeiramente menor que 90 graus. Inspire durante esta parte do movimento."],"tracking":"weight_reps"},{"id":"Chair_Squat","name":"Agachamento na Cadeira","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Ajuste a barra para uma altura adequada à sua estatura. Carregue a barra, posicione-se sob ela e apoie-a nas costas dos ombros.","Segure a barra com as palmas voltadas para frente, destrave-a e levante-a do suporte estendendo as pernas.","Dê um passo à frente, cerca de 45 cm, posicionando os pés na largura dos ombros com os dedos ligeiramente para fora. Mantenha o olhar para frente e a coluna neutra ou levemente arqueada. Esta é a posição inicial.","Abaixe a barra lentamente, flexionando os joelhos e mantendo a postura ereta, até que as coxas fiquem paralelas ao chão ou um pouco abaixo."],"tracking":"weight_reps"},{"id":"Elevated_Back_Lunge","name":"Afundo Posterior Elevado","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["quadriceps"],"secondaryMuscles":["gluteos","isquiotibiais"],"category":"forca","instructions":["Posicione uma barra em um suporte na altura dos ombros, com o peso adequado. Coloque uma plataforma baixa atrás de você.","Apoie a barra na parte superior das costas, mantendo as costas arqueadas e firmes. Suba na plataforma com os dois pés. Esta será sua posição inicial.","Dê um passo para trás com uma perna, flexionando quadris e joelhos até o joelho tocar o chão.","Pause e estenda quadris e joelhos para levantar, retornando à posição inicial antes de alternar as pernas."],"tracking":"weight_reps"},{"id":"Dumbbell_Squat","name":"Agachamento com Halteres","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais","inferior-das-costas"],"category":"forca","instructions":["Fique em pé segurando um halter em cada mão (palmas voltadas para as pernas).","Posicione as pernas na largura dos ombros, com os pés levemente apontados para fora. Mantenha a cabeça erguida e as costas retas. Esta é sua posição inicial.","Abaixe o torso lentamente, flexionando os joelhos, até que as coxas fiquem paralelas ao chão. Dica: Os joelhos não devem ultrapassar a linha dos dedos dos pés.","Empurre o chão com os calcanhares para retornar à posição inicial, expirando."],"tracking":"weight_reps"},{"id":"Cable_Hip_Adduction","name":"Adução de Quadril na Polia","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["quadriceps"],"secondaryMuscles":[],"category":"forca","instructions":["Fique de frente para uma polia baixa, com uma perna próxima à polia e a outra afastada.","Prenda a tornozeira no cabo e no tornozelo da perna próxima à polia.","Afaste-se da pilha de pesos com uma postura ampla e segure a barra da polia.","Fique na perna sem tornozeira e deixe a perna com tornozeira ser puxada em direção à polia. Esta é a posição inicial."],"tracking":"weight_reps"},{"id":"Barbell_Hack_Squat","name":"Agachamento Hack com Barra","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","antebracos","isquiotibiais"],"category":"forca","instructions":["Fique em pé segurando uma barra atrás de você com os braços estendidos e os pés na largura dos ombros. Dica: Segure a barra com as palmas voltadas para trás e use straps de pulso para melhor aderência. Esta é a posição inicial.","Mantendo a cabeça erguida, olhos para frente e costas retas, agache até as coxas ficarem paralelas ao chão. Inspire enquanto desce lentamente.","Empurre principalmente com os calcanhares e contraia as coxas para retornar à posição inicial, expirando.","Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Smith_Machine_Leg_Press","name":"Leg Press no Smith Machine","force":"push","level":"intermediario","mechanic":"composto","equipment":"maquina","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Posicione a barra do Smith Machine a alguns centímetros do chão, apoiada nas travas. Após carregar o peso adequado, deite-se sob a barra. Coloque a parte média dos pés na barra, com os joelhos próximos ao peito. Esta é a posição inicial.","Inicie o movimento empurrando com os pés para levantar a barra, estendendo quadris e joelhos. Não trave os joelhos.","No topo do movimento, faça uma pausa breve antes de retornar à posição inicial."],"tracking":"weight_reps"},{"id":"Barbell_Walking_Lunge","name":"Afundo Caminhando com Barra","force":"push","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Comece em pé, com os pés na largura dos ombros e uma barra apoiada na parte superior das costas.","Dê um passo à frente com uma perna, flexionando os joelhos para abaixar os quadris. Desça até o joelho de trás quase tocar o chão. Mantenha a postura ereta e o joelho da frente acima do pé da frente.","Empurre com o calcanhar do pé da frente e estenda ambos os joelhos para levantar-se novamente.","Dê um passo à frente com o pé de trás, repetindo o afundo com a perna oposta."],"tracking":"weight_reps"},{"id":"Barbell_Full_Squat","name":"Agachamento Livre com Barra","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais","inferior-das-costas"],"category":"forca","instructions":["Posicione a barra em um rack logo acima da altura dos ombros. Coloque-se sob a barra, apoiando-a nas costas dos ombros (logo abaixo do pescoço).","Segure a barra com as duas mãos e levante-a do rack empurrando com as pernas e endireitando o tronco.","Afaste-se do rack e posicione as pernas na largura dos ombros, com os pés levemente apontados para fora. Mantenha a cabeça erguida e as costas retas. Esta será sua posição inicial.","Comece a descer lentamente, dobrando os joelhos e sentando com os quadris, mantendo a postura reta. Desça até que os isquiotibiais toquem as panturrilhas, inspirando."],"tracking":"weight_reps"},{"id":"Plie_Dumbbell_Squat","name":"Agachamento Sumô com Halter","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["quadriceps"],"secondaryMuscles":["abdominais","panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Segure um halter pela base com as duas mãos e fique em pé com as pernas afastadas além da largura dos ombros e joelhos levemente flexionados.","Os pés devem estar apontados para fora. Dica: os braços devem ficar imóveis durante o exercício. Esta é a posição inicial.","Flexione os joelhos lentamente e abaixe-se até que as coxas fiquem paralelas ao chão. Inspire durante essa fase excêntrica.","Empurre principalmente com os calcanhares para voltar à posição inicial enquanto expira."],"tracking":"weight_reps"},{"id":"Cable_Deadlifts","name":"Levantamento Terra na Polia","force":"pull","level":"iniciante","mechanic":"composto","equipment":"cabo","primaryMuscles":["quadriceps"],"secondaryMuscles":["antebracos","gluteos","isquiotibiais","inferior-das-costas"],"category":"forca","instructions":["Ajuste os cabos para a parte baixa das torres e selecione o peso. Fique entre as torres.","Agache-se flexionando quadris e joelhos até alcançar as alças.","Segure as alças e levante-se, estendendo quadris e joelhos, mantendo os braços estendidos e o peito erguido.","Ao ficar em pé, retorne à posição inicial e repita."],"tracking":"weight_reps"},{"id":"Smith_Single-Leg_Split_Squat","name":"Agachamento Búlgaro no Smith","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Posicione um banco plano atrás da máquina Smith. Ajuste a barra para sua altura. Com a barra carregada, posicione-se sob ela, apoiando-a nas costas dos ombros.","Segure a barra com as duas mãos nas laterais, destrave-a e levante-a do suporte empurrando com as pernas e endireitando o tronco.","Posicione uma perna levemente para frente sob a barra e estenda a outra para trás, apoiando o peito do pé no banco. Esta é a posição inicial.","Abaixe a barra lentamente dobrando o joelho da perna da frente, mantendo a postura reta e a cabeça erguida. Desça até a coxa ficar abaixo do paralelo com o chão. Inspire durante esse movimento. Dica: O joelho não deve passar a linha dos dedos do pé."],"tracking":"weight_reps"},{"id":"Dumbbell_Rear_Lunge","name":"Afundo Posterior com Halteres","force":"push","level":"intermediario","mechanic":"composto","equipment":"halteres","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Fique em pé com o torso ereto, segurando dois halteres ao lado do corpo. Esta é a posição inicial.","Dê um passo para trás com a perna direita, cerca de 60 cm da esquerda, e abaixe o corpo, mantendo o torso ereto e o equilíbrio. Inspire ao descer. Evite que o joelho da frente ultrapasse a ponta dos pés.","Expire e empurre com a ponta dos pés (para quadríceps) ou calcanhares (para glúteos) para voltar à posição inicial.","Repita com a perna oposta."],"tracking":"weight_reps"},{"id":"Barbell_Side_Split_Squat","name":"Agachamento Lateral com Barra","force":"push","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","isquiotibiais","inferior-das-costas"],"category":"forca","instructions":["Fique em pé, segurando uma barra apoiada nas costas dos ombros (ligeiramente abaixo do pescoço). Os pés devem estar bem afastados, com o pé da perna da frente virado para o lado. Esta será a posição inicial.","Abaixe o corpo em direção ao lado do pé virado, flexionando o joelho e o quadril da perna da frente, enquanto mantém a perna oposta levemente flexionada. Inspire enquanto abaixa o corpo.","Retorne à posição inicial estendendo o quadril e o joelho da perna da frente. Expire enquanto executa este movimento.","Após realizar a quantidade recomendada de repetições, repita o movimento com a perna oposta."],"tracking":"weight_reps"},{"id":"Narrow_Stance_Leg_Press","name":"Leg Press com Postura Fechada","force":"push","level":"intermediario","mechanic":"composto","equipment":"maquina","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Sente-se na máquina de leg press e coloque as pernas na plataforma com uma postura mais fechada que a largura dos ombros, dedos dos pés ligeiramente apontados para fora. Os pés devem estar cerca de 7 cm ou menos de distância. Dica: Mantenha a cabeça erguida e as costas apoiadas no encosto.","Abaixe as travas de segurança e empurre a plataforma até que as pernas estejam totalmente estendidas à sua frente. Dica: Não trave os joelhos. O torso e as pernas devem formar um ângulo de 90 graus. Esta será a posição inicial.","Inspire e abaixe lentamente a plataforma até que as coxas e as panturrilhas formem um ângulo de 90 graus.","Empurre principalmente com os calcanhares, usando os quadríceps, para voltar à posição inicial enquanto expira."],"tracking":"weight_reps"},{"id":"Narrow_Stance_Squats","name":"Agachamento com Postura Fechada","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais","inferior-das-costas"],"category":"forca","instructions":["Para segurança, realize este exercício dentro de um rack de agachamento. Ajuste a barra na altura adequada e carregue-a. Posicione-se sob a barra, apoiando-a nas costas dos ombros (logo abaixo do pescoço).","Segure a barra com as duas mãos e levante-a do rack empurrando com as pernas e endireitando o torso.","Afaste-se do rack e posicione as pernas com uma postura mais fechada que a largura dos ombros, dedos dos pés ligeiramente apontados para fora. Os pés devem estar entre 7-15 cm de distância. Mantenha a cabeça erguida e as costas retas. Esta será a posição inicial.","Comece a abaixar a barra flexionando os joelhos, mantendo a postura reta. Desça até que o ângulo entre as coxas e as panturrilhas fique ligeiramente menor que 90 graus. Inspire durante essa parte. Dica: Os joelhos devem alinhar-se com os dedos dos pés; se passarem deles, a técnica está incorreta."],"tracking":"weight_reps"},{"id":"Smith_Machine_Pistol_Squat","name":"Agachamento Pistol no Smith Machine","force":"push","level":"intermediario","mechanic":"composto","equipment":"maquina","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Ajuste a barra para uma altura que combine com sua estatura. Posicione-se sob ela, apoiando a barra nas costas dos ombros.","Segure a barra com as mãos para frente, desengate-a e levante-a estendendo as pernas.","Coloque um pé cerca de 30 cm à frente da barra. Estenda a outra perna para frente, mantendo-a fora do chão. Olhe para frente e mantenha a coluna neutra ou levemente arqueada. Esta é a posição inicial.","Mantendo uma boa postura, abaixe-se flexionando o joelho e o quadril, indo o mais baixo que a flexibilidade permitir."],"tracking":"weight_reps"},{"id":"Narrow_Stance_Hack_Squats","name":"Agachamento Hack com Postura Fechada","force":"push","level":"intermediario","mechanic":"composto","equipment":"maquina","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais"],"category":"forca","instructions":["Apoie as costas no encosto da máquina e encaixe os ombros sob as almofadas de apoio.","Posicione as pernas na plataforma com uma postura mais fechada que a largura dos ombros, dedos dos pés ligeiramente apontados para fora. Os pés devem estar cerca de 7 cm ou menos de distância. Dica: Mantenha a cabeça erguida e as costas sempre apoiadas no encosto.","Coloque os braços nas alças laterais da máquina e desengate as travas de segurança (geralmente girando as alças de uma posição frontal para diagonal).","Estenda as pernas sem travar os joelhos. Esta será a posição inicial."],"tracking":"weight_reps"},{"id":"Dumbbell_Squat_To_A_Bench","name":"Agachamento até o Banco com Halteres","force":"push","level":"intermediario","mechanic":"composto","equipment":"halteres","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais","inferior-das-costas"],"category":"forca","instructions":["Fique em pé com um banco plano atrás de você, segurando um halter em cada mão (palmas voltadas para as pernas).","Posicione as pernas na largura dos ombros, com os pés levemente apontados para fora. Mantenha a cabeça erguida e as costas retas. Esta é sua posição inicial.","Abaixe o torso lentamente, flexionando os joelhos, até tocar levemente o banco atrás, inspirando. Dica: Evite que os joelhos ultrapassem os dedos dos pés.","Empurre o chão com os calcanhares para retornar à posição inicial, expirando."],"tracking":"weight_reps"},{"id":"Wide_Stance_Barbell_Squat","name":"Agachamento com Barra em Pé Afastado","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos","isquiotibiais","inferior-das-costas"],"category":"forca","instructions":["Este exercício é melhor realizado dentro de um rack de agachamento por segurança. Comece ajustando a barra em uma altura adequada. Após carregar a barra, posicione-se sob ela, apoiando-a nas costas dos ombros (logo abaixo do pescoço).","Segure a barra com as duas mãos e levante-a do rack empurrando com as pernas e endireitando o tronco.","Afaste-se do rack e posicione as pernas em uma base mais larga que os ombros, com os pés ligeiramente voltados para fora. Mantenha a cabeça erguida e as costas retas. Esta é a posição inicial.","Comece a descer lentamente, flexionando os joelhos e mantendo a postura ereta. Desça até que as coxas fiquem abaixo do paralelo com o chão (ângulo menor que 90 graus). Inspire durante essa fase. Dica: Os joelhos não devem ultrapassar a linha dos pés."],"tracking":"weight_reps"},{"id":"Front_Squats_With_Two_Kettlebells","name":"Agachamento Frontal com Dois Kettlebells","force":"push","level":"intermediario","mechanic":"composto","equipment":"kettlebell","primaryMuscles":["quadriceps"],"secondaryMuscles":["panturrilhas","gluteos"],"category":"forca","instructions":["Leve dois kettlebells aos ombros, estendendo as pernas e quadris para puxá-los, girando os pulsos.","Olhe sempre para frente, agache o máximo possível e pause no fundo. Ao agachar, empurre os joelhos para fora, mantendo o torso ereto e o peito para cima.","Volte à posição inicial empurrando pelos calcanhares e repita."],"tracking":"weight_reps"},{"id":"Leverage_Deadlift","name":"Levantamento Terra na Máquina de Alavanca","force":"pull","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["quadriceps"],"secondaryMuscles":["gluteos","isquiotibiais"],"category":"forca","instructions":["Posicione-se entre as alças, segure-as com uma pegada confortável e abaixe os quadris, mantendo o peito erguido e olhando para frente. Esta é a posição inicial.","Estenda os quadris e joelhos para levantar o peso, mantendo as costas retas.","Volte o peso à posição inicial com controle."],"tracking":"weight_reps"},{"id":"Upright_Cable_Row","name":"Remada Alta no Cabo","force":"pull","level":"intermediario","mechanic":"composto","equipment":"cabo","primaryMuscles":["trapezio"],"secondaryMuscles":["ombros"],"category":"forca","instructions":["Segure uma barra reta no cabo com pegada pronada, mãos ligeiramente mais próximas que a largura dos ombros. Braços estendidos.","Eleve a barra puxando os cotovelos para cima, mantendo-a próxima ao corpo até quase tocar o queixo.","Abaixe a barra lentamente e repita."],"tracking":"weight_reps"},{"id":"Smith_Machine_Upright_Row","name":"Remada Alta no Smith","force":"pull","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["trapezio"],"secondaryMuscles":["biceps","meio-das-costas","ombros"],"category":"forca","instructions":["Ajuste a barra na máquina Smith para a altura das coxas. Com a barra carregada, segure-a com as palmas para frente e as mãos na largura dos ombros. Use straps se necessário.","Levante a barra com os braços estendidos e costas retas. Mantenha os cotovelos levemente flexionados. Esta é a posição inicial.","Use os ombros laterais para levantar a barra enquanto expira, mantendo-a próxima ao corpo. Eleve até quase tocar o queixo. Dica: Os cotovelos devem conduzir o movimento, ficando acima dos antebraços. Mantenha o tronco imóvel e pause no topo.","Abaixe a barra lentamente à posição inicial enquanto inspira."],"tracking":"weight_reps"},{"id":"Cable_Shrugs","name":"Encolhimento no Pulley","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["trapezio"],"secondaryMuscles":[],"category":"forca","instructions":["Segure uma barra de cabo acoplada a uma polia baixa com uma pegada pronada (palmas para baixo) na largura dos ombros ou um pouco mais larga.","Fique em pé, ereto, perto da polia, com os braços estendidos à frente segurando a barra. Esta é a posição inicial.","Levante a barra elevando os ombros o mais alto possível enquanto expira. Mantenha a contração no topo por um segundo. Dica: Mantenha os braços estendidos; evite usar os bíceps. Apenas os ombros devem se mover.","Abaixe a barra de volta à posição inicial."],"tracking":"weight_reps"},{"id":"Leverage_Shrug","name":"Encolhimento com Alavanca","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["trapezio"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Carregue os pinos com um peso adequado. Posicione-se diretamente entre as alças.","Segure as alças superiores com uma pegada confortável e abaixe os quadris enquanto inspira. Olhe para frente com a cabeça erguida e mantenha o peito para cima.","Empurre o chão com os calcanhares, estendendo os quadris e joelhos até ficar em pé. Mantenha os braços retos durante o movimento, terminando com os ombros para trás. Esta será a posição inicial.","Levante o peso encolhendo os ombros em direção às orelhas, movendo-se reto para cima e para baixo."],"tracking":"weight_reps"},{"id":"Standing_Dumbbell_Upright_Row","name":"Remada Alta com Halteres em Pé","force":"pull","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["trapezio"],"secondaryMuscles":["biceps","ombros"],"category":"forca","instructions":["Segure um halter em cada mão com pegada pronada (palmas para frente) ligeiramente mais estreita que a largura dos ombros. Halteres repousando sobre as coxas. Braços estendidos com leve flexão nos cotovelos e costas retas. Esta é a posição inicial.","Use os ombros para levantar os halteres ao expirar. Mantenha os halteres próximos ao corpo, com os cotovelos conduzindo o movimento. Continue até quase tocar o queixo. Faça uma pausa no topo.","Abaixe os halteres lentamente à posição inicial, inspirando.","Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Kettlebell_Sumo_High_Pull","name":"Puxada Alta Sumô com Kettlebell","force":"pull","level":"intermediario","mechanic":"composto","equipment":"kettlebell","primaryMuscles":["trapezio"],"secondaryMuscles":["adutores","gluteos","isquiotibiais","quadriceps","ombros"],"category":"forca","instructions":["Posicione um kettlebell no chão entre os pés, com os pés afastados em uma postura ampla. Segure o kettlebell com as duas mãos, jogue os quadris para trás e mantenha o peito e a cabeça erguidos.","Estenda os quadris e joelhos, puxando o kettlebell em direção aos ombros e elevando os cotovelos. Retorne à posição inicial."],"tracking":"weight_reps"},{"id":"Barbell_Shrug","name":"Encolhimento de Ombros com Barra","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["trapezio"],"secondaryMuscles":[],"category":"forca","instructions":["Fique em pé com os pés na largura dos ombros, segurando uma barra com as duas mãos na frente do corpo, com pegada pronada (palmas voltadas para as coxas). Dica: As mãos devem estar um pouco mais largas que os ombros; use straps para melhor aderência. Esta é a posição inicial.","Eleve os ombros o máximo possível, expirando e segurando a contração por um segundo. Dica: Não use os bíceps para levantar a barra.","Retorne lentamente à posição inicial inspirando.","Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Upright_Row_-_With_Bands","name":"Remada Alta com Faixas Elásticas","force":"pull","level":"iniciante","mechanic":"composto","equipment":"faixas","primaryMuscles":["trapezio"],"secondaryMuscles":["ombros"],"category":"forca","instructions":["Fique em cima de uma faixa elástica para criar tensão. Segure as alças com pegada pronada, mãos ligeiramente mais próximas que a largura dos ombros.","Eleve as alças puxando os cotovelos para cima, mantendo-as próximas ao corpo até quase tocar o queixo.","Abaixe as alças lentamente e repita."],"tracking":"weight_reps"},{"id":"Dumbbell_Shrug","name":"Encolhimento de Ombros com Halteres","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["trapezio"],"secondaryMuscles":[],"category":"forca","instructions":["Fique em pé com um halter em cada mão (palmas voltadas para o corpo), braços estendidos ao lado do corpo.","Eleve os ombros o mais alto possível, expirando. Segure a contração no topo por um segundo. Dica: Mantenha os braços estendidos; não use os bíceps. Apenas os ombros devem se mover.","Abaixe os halteres de volta à posição original.","Repita para o número de repetições recomendado."],"tracking":"weight_reps"},{"id":"Barbell_Shrug_Behind_The_Back","name":"Encolhimento com Barra Atrás das Costas","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["trapezio"],"secondaryMuscles":["antebracos","meio-das-costas"],"category":"forca","instructions":["Fique em pé, com os pés na largura dos ombros, segurando uma barra com ambas as mãos atrás das costas, usando uma pegada pronada (palmas voltadas para trás). Dica: As mãos devem estar um pouco mais afastadas que a largura dos ombros. Você pode usar straps para melhor aderência. Esta será a posição inicial.","Levante os ombros o mais alto possível enquanto expira e mantenha a contração por um segundo. Dica: Evite levantar a barra usando os bíceps. Os braços devem permanecer estendidos o tempo todo.","Retorne lentamente à posição inicial enquanto inspira.","Repita para a quantidade recomendada de repetições."],"tracking":"weight_reps"},{"id":"Smith_Machine_Behind_the_Back_Shrug","name":"Encolhimento de Ombros Atrás das Costas no Smith","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["trapezio"],"secondaryMuscles":["ombros"],"category":"forca","instructions":["Com a barra na altura das coxas, carregue um peso adequado.","Fique em pé com a barra atrás de você, segurando-a com uma pegada pronada na largura dos ombros e solte o peso. Mantenha-se ereto, com a cabeça e o peito erguidos e os braços estendidos. Esta é a posição inicial.","Inicie o movimento encolhendo os ombros diretamente para cima. Não flexione os braços ou pulsos durante o movimento.","Após uma breve pausa, retorne o peso à posição inicial."],"tracking":"weight_reps"},{"id":"Calf-Machine_Shoulder_Shrug","name":"Encolhimento de Ombros na Máquina de Panturrilha","force":"pull","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["trapezio"],"secondaryMuscles":[],"category":"forca","instructions":["Posicione-se na máquina de panturrilha com as almofadas acima dos ombros. Torso reto e braços estendidos ao lado do corpo. Esta é a posição inicial.","Eleve os ombros em direção às orelhas enquanto expira e segure a contração por um segundo.","Retorne lentamente à posição inicial enquanto inspira.","Repita para a quantidade recomendada de repetições."],"tracking":"weight_reps"},{"id":"Triceps_Pushdown","name":"Tríceps Pulley","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Prenda uma barra reta ou angular em uma polia alta e segure com pegada pronada (palmas para baixo) na largura dos ombros.","Fique em pé com o tronco reto e leve uma pequena inclinação para frente. Mantenha os braços superiores próximos ao corpo e perpendiculares ao chão, com os antebraços apontando para a polia. Esta é a posição inicial.","Use o tríceps para levar a barra para baixo até tocar a frente das coxas, com os braços totalmente estendidos. Os braços superiores devem permanecer imóveis; apenas os antebraços se movem. Expire ao fazer este movimento.","Após uma pausa de um segundo na posição contraída, levante a barra lentamente à posição inicial. Inspire ao fazer este passo."],"tracking":"weight_reps"},{"id":"Bench_Dips","name":"Mergulho no Banco","force":"push","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Para este exercício, posicione um banco atrás de suas costas. Com o banco perpendicular ao seu corpo e de costas para ele, segure a borda do banco com as mãos totalmente estendidas, afastadas na largura dos ombros. Estenda as pernas para a frente, dobradas na cintura e perpendiculares ao tronco. Esta será a posição inicial.","Abaixe o corpo lentamente, inspirando, ao dobrar os cotovelos até que o ângulo entre o braço e o antebraço seja ligeiramente menor que 90 graus. Dica: Mantenha os cotovelos o mais próximo possível durante o movimento. Os antebraços devem sempre apontar para baixo.","Use os tríceps para levantar o tronco de volta à posição inicial.","Repita para a quantidade recomendada de repetições."],"tracking":"reps"},{"id":"Dip_Machine","name":"Máquina de Mergulho","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Sente-se firmemente na máquina de mergulho, selecione o peso e segure as alças.","Mantenha os cotovelos junto ao corpo para focar no tríceps, com ângulo de 90 graus.","Contraia o tríceps e estenda os braços para baixo expirando. Dica: No final, mantenha leve flexão para não aliviar a tensão.","Deixe os braços voltarem lentamente à posição inicial inspirando."],"tracking":"weight_reps"},{"id":"Body_Tricep_Press","name":"Tríceps Press Corporal","force":"push","level":"iniciante","mechanic":"isolado","equipment":"peso-do-corpo","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Posicione uma barra em um suporte na altura do peito.","Em pé, segure a barra com as mãos na largura dos ombros e afaste-se um pouco, com os pés juntos e braços estendidos, inclinando-se sobre a barra. Esta é a posição inicial.","Flexione os cotovelos para baixar o corpo em direção à barra.","Faça uma pausa e, em seguida, estenda os cotovelos para retornar à posição inicial."],"tracking":"reps"},{"id":"Machine_Triceps_Extension","name":"Tríceps Pulley Máquina","force":"push","level":"iniciante","mechanic":"isolado","equipment":"maquina","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Ajuste o banco à altura adequada e selecione o peso. Apoie os braços superiores nas almofadas e segure as alças. Esta será sua posição inicial.","Estenda os cotovelos, afastando os antebraços dos braços superiores.","Faça uma pausa no final do movimento e retorne lentamente o peso à posição inicial.","Evite retornar o peso completamente até o final do conjunto para manter a tensão nos músculos."],"tracking":"weight_reps"},{"id":"Lying_Triceps_Press","name":"Tríceps Francês Deitado","force":"push","level":"intermediario","mechanic":"isolado","equipment":"barra-w","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se em um banco plano com uma barra W ou reta no chão atrás da cabeça e os pés no chão.","Segure a barra atrás de você com uma pegada média pronada e levante-a à sua frente com os braços estendidos. Dica: Braços perpendiculares ao torso e ao chão, cotovelos recolhidos. Esta é a posição inicial.","Inspirando, abaixe o peso lentamente até a barra tocar levemente a testa, mantendo os braços superiores e cotovelos estacionários.","Use os tríceps para levantar o peso de volta à posição inicial, expirando."],"tracking":"weight_reps"},{"id":"Tricep_Dumbbell_Kickback","name":"Tríceps Coice com Halter","force":"push","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Segure um halter em cada mão com as palmas voltadas para o corpo. Mantenha as costas retas, joelhos levemente flexionados e incline o tronco para frente, quase paralelo ao chão. Certifique-se de manter a cabeça erguida. Os braços superiores devem ficar próximos ao tronco e paralelos ao chão, com os antebraços apontando para baixo, formando um ângulo de 90 graus com os braços. Esta é a posição inicial.","Mantendo os braços superiores imóveis, expire e use o tríceps para levantar os pesos até os braços estarem totalmente estendidos, focando no movimento do antebraço.","Após uma breve pausa no topo, inspire e abaixe lentamente os halteres de volta à posição inicial.","Repita o movimento pelo número de repetições prescrito."],"tracking":"weight_reps"},{"id":"Triceps_Pushdown_-_Rope_Attachment","name":"Tríceps Pulley com Corda","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Prenda uma corda em uma polia alta e segure com pegada neutra (palmas voltadas uma para a outra).","Fique em pé com o tronco reto e leve uma pequena inclinação para frente. Mantenha os braços superiores próximos ao corpo e perpendiculares ao chão, com os antebraços apontando para a polia. Esta é a posição inicial.","Use o tríceps para puxar a corda para baixo, levando cada lado da corda para as laterais das coxas, até os braços estarem totalmente estendidos. Os braços superiores devem permanecer imóveis; apenas os antebraços se movem. Expire ao fazer este movimento.","Após segurar por um segundo na posição contraída, levante a corda lentamente à posição inicial. Inspire ao fazer este passo."],"tracking":"weight_reps"},{"id":"Dips_-_Triceps_Version","name":"Mergulho - Versão Tríceps","force":"push","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Segure-se nas barras paralelas com os braços quase estendidos.","Inspire e abaixe-se lentamente, mantendo o torso ereto e cotovelos próximos ao corpo para focar no tríceps, até formar 90 graus no cotovelo.","Expire e empurre o torso para cima usando o tríceps para voltar à posição inicial.","Repita para as repetições prescritas."],"tracking":"reps"},{"id":"EZ-Bar_Skullcrusher","name":"Tríceps Testa com Barra W","force":"push","level":"iniciante","mechanic":"isolado","equipment":"barra-w","primaryMuscles":["triceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Deitado em um banco, segure a barra W com uma pegada fechada, mantendo os cotovelos apontados para cima e os braços perpendiculares ao chão. Esta será sua posição inicial.","Mantendo a parte superior dos braços parada, flexione os cotovelos para baixar a barra em direção à testa. Inspire durante essa parte do movimento.","Estenda os cotovelos para levantar a barra de volta à posição inicial, expirando.","Repita."],"tracking":"weight_reps"},{"id":"Triceps_Pushdown_-_V-Bar_Attachment","name":"Tríceps Pulley com Barra V","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Prenda uma barra V em uma polia alta e segure com pegada pronada (palmas para baixo) na largura dos ombros, com os polegares mais altos que os mindinhos.","Fique em pé com o tronco reto e leve uma pequena inclinação para frente. Mantenha os braços superiores próximos ao corpo e perpendiculares ao chão, com os antebraços apontando para a polia. Esta é a posição inicial.","Use o tríceps para levar a barra para baixo até tocar a frente das coxas, com os braços totalmente estendidos. Os braços superiores devem permanecer imóveis; apenas os antebraços se movem. Expire ao fazer este movimento.","Após uma pausa de um segundo na posição contraída, levante a barra V lentamente à posição inicial. Inspire ao fazer este passo."],"tracking":"weight_reps"},{"id":"Reverse_Triceps_Bench_Press","name":"Supino Invertido para Tríceps","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Deite-se de costas em um banco reto. Com uma pegada fechada e supinada (largura dos ombros), levante a barra do suporte e segure-a estendida à sua frente, com os braços travados e perpendiculares ao chão. Esta é a posição inicial.","Enquanto inspira, desça a barra lentamente até sentir no meio do peito. Dica: Ao contrário do supino tradicional, mantenha os cotovelos próximos ao tronco para maximizar o trabalho do tríceps.","Após uma pausa de um segundo, retorne a barra à posição inicial enquanto expira e empurra com os tríceps. Trave os braços na posição contraída, segure por um segundo e desça lentamente. Dica: A descida deve levar pelo menos o dobro do tempo da subida.","Repita o movimento para a quantidade prescrita de repetições."],"tracking":"weight_reps"},{"id":"Cable_Rope_Overhead_Triceps_Extension","name":"Tríceps Corda Acima da Cabeça","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Conecte uma corda à polia baixa.","Segure a corda com as duas mãos acima da cabeça, usando uma pegada neutra (palmas viradas uma para a outra). Os cotovelos devem ficar próximos à cabeça e os braços perpendiculares ao chão. Esta é a posição inicial.","Abaixe a corda lentamente atrás da cabeça, mantendo a parte superior dos braços imóvel. Inspire e pause quando o tríceps estiver totalmente alongado.","Retorne à posição inicial contraindo o tríceps e expirando."],"tracking":"weight_reps"},{"id":"Smith_Machine_Close-Grip_Bench_Press","name":"Supino Fechado no Smith Machine","force":"push","level":"iniciante","mechanic":"composto","equipment":"maquina","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Posicione um banco plano sob o Smith Machine. Ajuste a barra para uma altura que você alcance deitado com os braços quase totalmente estendidos. Com o peso selecionado, deite-se no banco. Use uma pegada fechada e pronada (palmas para frente) na largura dos ombros, desengate a barra e segure-a reta acima de você com os braços travados. Esta é a posição inicial.","Inspire e desça lentamente até a barra tocar o meio do peito. Dica: Mantenha os cotovelos próximos ao torso para maximizar o trabalho do tríceps.","Após uma pausa de um segundo, retorne a barra à posição inicial enquanto expira, empurrando com os tríceps. Trave os braços na posição contraída, segure por um segundo e desça novamente. Dica: A descida deve ser pelo menos duas vezes mais lenta que a subida.","Repita o movimento pelo número prescrito de repetições."],"tracking":"weight_reps"},{"id":"Cable_Lying_Triceps_Extension","name":"Tríceps Francês na Polia Deitado","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se em um banco plano e segure a barra reta da polia baixa com uma pegada fechada e pronada (palmas para baixo). Dica: A maneira mais fácil é pedir para alguém entregar a barra enquanto você se deita.","Com os braços estendidos, posicione a barra sobre o torso. Seus braços e torso devem formar um ângulo de 90 graus. Esta será a posição inicial.","Abaixe a barra flexionando os cotovelos, mantendo a parte superior dos braços imóvel e os cotovelos para dentro. Desça até a barra tocar levemente a testa. Inspire durante essa fase.","Contraia o tríceps para levantar a barra de volta à posição inicial. Expire durante essa fase."],"tracking":"weight_reps"},{"id":"Low_Cable_Triceps_Extension","name":"Extensão de Tríceps na Polia Baixa","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Selecione o peso desejado e deite-se de barriga para cima no banco de uma máquina de remada sentada com uma corda presa. Sua cabeça deve apontar para a fixação.","Segure as extremidades externas da corda com as palmas voltadas uma para a outra (pegada neutra).","Posicione os cotovelos em um ângulo de 90 graus, com os braços superiores perpendiculares ao torso. Dica: Mantenha os cotovelos para dentro e certifique-se de que os braços superiores apontem para o teto enquanto os antebraços apontam para a polia acima da cabeça. Esta será a posição inicial.","Ao expirar, estenda os antebraços até ficarem retos e verticais. Os braços superiores e cotovelos permanecem imóveis. Apenas os antebraços devem se mover. Contraia os tríceps fortemente por um segundo."],"tracking":"weight_reps"},{"id":"Incline_Push-Up_Close-Grip","name":"Flexão Inclinada com Pegada Fechada","force":"push","level":"iniciante","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Fique de frente para a barra de um Smith machine ou plataforma elevada na altura adequada.","Coloque as mãos próximas uma da outra na barra.","Posicione os pés afastados da barra, com braços e corpo retos. Esta é a posição inicial.","Mantendo o corpo reto, abaixe o peito até a barra dobrando os braços."],"tracking":"reps"},{"id":"Close-Grip_Push-Up_off_of_a_Dumbbell","name":"Flexão em Pegada Fechada com Halter","force":"push","level":"intermediario","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["triceps"],"secondaryMuscles":["abdominais","peito","ombros"],"category":"forca","instructions":["Deite-se no chão e coloque as mãos em um halter na vertical. Apoie o peso na ponta dos pés e nas mãos, mantendo o torso rígido e os cotovelos para dentro, com os braços retos. Esta será sua posição inicial.","Abaixe o corpo, flexionando os cotovelos enquanto inspira. Mantenha o corpo reto, sem deixar os quadris subirem ou caírem.","Empurre-se de volta à posição inicial estendendo os cotovelos. Expire ao executar esta etapa.","Após uma pausa na posição contraída, repita o movimento pelo número prescrito de repetições."],"tracking":"reps"},{"id":"Reverse_Grip_Triceps_Pushdown","name":"Tríceps Pulley com Pegada Invertida","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Ajuste uma barra (reta ou EZ) em uma máquina de pulley alto.","De frente para a barra, segure-a com as palmas voltadas para cima (pegada supinada) na largura dos ombros. Baixe a barra usando as costas até os braços ficarem totalmente estendidos ao lado do corpo. Dica: Os cotovelos devem ficar próximos ao corpo e os pés afastados na largura dos ombros. Esta é a posição inicial.","Eleve lentamente a barra para cima enquanto inspira, alinhando-a com o peito. Apenas os antebraços devem se mover; cotovelos e braços superiores ficam imóveis ao lado do corpo.","Em seguida, comece a baixar a barra de volta à posição inicial enquanto expira e contrai o tríceps com força."],"tracking":"weight_reps"},{"id":"Standing_Towel_Triceps_Extension","name":"Extensão de Tríceps com Toalha em Pé","force":"push","level":"iniciante","mechanic":"isolado","equipment":"peso-do-corpo","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Fique em pé com os braços totalmente estendidos acima da cabeça, segurando uma extremidade de uma toalha com as duas mãos. Os cotovelos devem estar próximos à cabeça e os braços perpendiculares ao chão, com as palmas voltadas uma para a outra. Os pés devem estar afastados na largura dos ombros. Esta é a posição inicial.","Comunique-se com seu parceiro para que ele segure a outra extremidade da toalha e aplique resistência. Mantenha os braços superiores próximos à cabeça e perpendiculares ao chão, abaixe a resistência em um movimento semicircular atrás da cabeça até os antebraços tocarem os bíceps. Dica: Apenas os antebraços devem se mover. Inspire ao executar este passo.","Volte à posição inicial usando o tríceps para levantar a toalha. Expire ao executar este passo.","Repita para a quantidade recomendada de repetições."],"tracking":"reps"},{"id":"Close-Grip_EZ-Bar_Press","name":"Supino com Barra W em Pegada Fechada","force":"push","level":"iniciante","mechanic":"composto","equipment":"barra-w","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Deite-se em um banco reto com uma barra W carregada com o peso apropriado.","Usando uma pegada fechada, levante a barra e segure-a reta acima do torso, com os cotovelos para dentro. Os braços devem ficar perpendiculares ao chão. Esta será sua posição inicial.","Agora, baixe a barra em direção ao peito inferior enquanto inspira. Mantenha os cotovelos para dentro durante o movimento.","Usando o tríceps para empurrar a barra para cima, pressione-a de volta à posição inicial estendendo os cotovelos enquanto expira."],"tracking":"weight_reps"},{"id":"Push-Ups_-_Close_Triceps_Position","name":"Flexão com Apoio Fechada para Tríceps","force":"push","level":"intermediario","mechanic":"composto","equipment":"peso-do-corpo","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Deite-se de bruços no chão e posicione as mãos mais próximas que a largura dos ombros. Mantenha o torso elevado com os braços estendidos.","Inspire e abaixe-se até o peito quase tocar o chão.","Use os tríceps e parte dos peitorais para empurrar o corpo de volta à posição inicial, contraindo o peito. Expire ao fazer isso.","Após uma pausa de um segundo na posição contraída, repita o movimento pelo número de repetições prescrito."],"tracking":"reps"},{"id":"Close-Grip_Dumbbell_Press","name":"Supino com Halteres em Pegada Fechada","force":"push","level":"iniciante","mechanic":"composto","equipment":"halteres","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Coloque um halter em pé em um banco reto.","Garantindo que o halter fique seguro no topo do banco, deite-se perpendicular ao banco com apenas os ombros apoiados na superfície. Os quadris devem ficar abaixo do banco e as pernas flexionadas, com os pés firmes no chão.","Segure o halter com as duas mãos e segure-o reto acima do peito, com os braços estendidos. Ambas as palmas devem pressionar a parte inferior dos lados do halter. Esta será sua posição inicial.","Inicie o movimento baixando o halter em direção ao peito."],"tracking":"weight_reps"},{"id":"Cable_Incline_Triceps_Extension","name":"Extensão de Tríceps Inclinada na Polia","force":"push","level":"iniciante","mechanic":"isolado","equipment":"cabo","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se em um banco inclinado de costas para uma polia alta com barra reta.","Segure a barra com pegada pronada estreita (palmas para baixo) e cotovelos junto ao corpo, formando um ângulo de 25° com o chão. Esta é a posição inicial.","Mantenha os braços superiores parados e estenda os braços contraindo o tríceps, expirando e segurando a contração por um segundo.","Retorne lentamente à posição inicial."],"tracking":"weight_reps"},{"id":"Standing_Dumbbell_Triceps_Extension","name":"Extensão de Tríceps com Halteres em Pé","force":"push","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Em pé, segure um halter com as duas mãos. Pés na largura dos ombros. Levante o halter acima da cabeça até os braços ficarem totalmente estendidos.","O peso deve repousar nas palmas das mãos, com os polegares ao redor, palmas para cima. Esta é a posição inicial.","Mantendo a parte superior dos braços próxima à cabeça, cotovelos para dentro e perpendiculares ao chão, abaixe o peso em movimento semicircular atrás da cabeça até os antebraços tocarem o bíceps. Inspire ao fazer isso.","Retorne à posição inicial usando o tríceps para levantar o halter. Expire ao fazer isso."],"tracking":"weight_reps"},{"id":"Close-Grip_Barbell_Bench_Press","name":"Supino Reto com Barra em Pegada Fechada","force":"push","level":"iniciante","mechanic":"composto","equipment":"barra","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Deite-se de costas em um banco reto. Usando uma pegada fechada (aproximadamente na largura dos ombros), levante a barra do suporte e segure-a reta acima de você com os braços travados. Esta será sua posição inicial.","Enquanto inspira, desça lentamente até sentir a barra no meio do peito. Dica: Ao contrário do supino reto comum, mantenha os cotovelos próximos ao torso o tempo todo para maximizar o envolvimento do tríceps.","Após uma pausa de um segundo, traga a barra de volta à posição inicial enquanto expira e empurra a barra usando os músculos do tríceps. Trave os braços na posição contraída, segure por um segundo e então comece a descer lentamente novamente. Dica: Deve levar pelo menos o dobro do tempo para descer do que para subir.","Repita o movimento pelo número prescrito de repetições."],"tracking":"weight_reps"},{"id":"Lying_Dumbbell_Tricep_Extension","name":"Extensão de Tríceps com Halteres Deitado","force":"push","level":"intermediario","mechanic":"isolado","equipment":"halteres","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Deite-se em um banco plano segurando dois halteres diretamente à sua frente. Os braços devem estar totalmente estendidos em um ângulo de 90 graus com o torso e o chão. As palmas devem estar voltadas para dentro e os cotovelos próximos ao corpo. Esta é a posição inicial.","Ao inspirar e mantendo a parte superior dos braços estacionária com os cotovelos fixos, abaixe lentamente o peso até os halteres ficarem próximos às orelhas.","Nesse ponto, mantendo os cotovelos fixos e a parte superior dos braços estacionária, use o tríceps para levantar o peso de volta à posição inicial enquanto expira.","Repita pelo número recomendado de repetições."],"tracking":"weight_reps"},{"id":"Decline_Dumbbell_Triceps_Extension","name":"Extensão de Tríceps Declinada com Halteres","force":"push","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Prenda as pernas na extremidade do banco declinado e deite-se com um halter em cada mão sobre as coxas, palmas voltadas uma para a outra.","Ao deitar, posicione os halteres à frente na largura dos ombros, com os braços estendidos e perpendiculares ao chão. Esta é a posição inicial.","Inspire e, mantendo os braços superiores imóveis e cotovelos para dentro, desça os halteres em um movimento semicircular até os polegares ficarem próximos às orelhas.","Contraia o tríceps para levantar os halteres à posição inicial, expirando."],"tracking":"weight_reps"},{"id":"Incline_Barbell_Triceps_Extension","name":"Extensão de Tríceps com Barra em Inclinação","force":"push","level":"intermediario","mechanic":"isolado","equipment":"barra","primaryMuscles":["triceps"],"secondaryMuscles":["antebracos"],"category":"forca","instructions":["Segure uma barra com pegada pronada (palmas para baixo) um pouco mais próxima que a largura dos ombros.","Deite-se em um banco inclinado ajustado entre 45-75 graus.","Leve a barra acima da cabeça com os braços estendidos e cotovelos para dentro. Os braços devem estar alinhados com o tronco. Esta será a posição inicial.","Abaixe a barra em um movimento semicircular atrás da cabeça até os antebraços tocarem os bíceps. Inspire ao fazer isso. Dica: Mantenha os braços superiores parados e próximos à cabeça; apenas os antebraços se movem."],"tracking":"weight_reps"},{"id":"Decline_EZ_Bar_Triceps_Extension","name":"Tríceps Francês no Banco Declinado com Barra W","force":"push","level":"iniciante","mechanic":"isolado","equipment":"barra","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Prenda as pernas na extremidade do banco declinado e deite-se lentamente.","Com uma pegada fechada (ligeiramente menor que a largura dos ombros), levante a barra W do suporte e segure-a reta acima de você, com os braços travados e cotovelos para dentro. Os braços devem estar perpendiculares ao chão. Esta é a posição inicial. Dica: Para proteger o manguito rotador, é melhor ter um ajudante para levantar a barra.","Inspire e, mantendo a parte superior dos braços parada, abaixe a barra lentamente em um movimento semicircular até tocar levemente a testa. Inspire durante essa fase.","Levante a barra de volta à posição inicial contraindo o tríceps e expirando."],"tracking":"weight_reps"},{"id":"Dumbbell_Tricep_Extension_-Pronated_Grip","name":"Extensão de Tríceps com Halteres - Pegada Pronada","force":"push","level":"iniciante","mechanic":"isolado","equipment":"halteres","primaryMuscles":["triceps"],"secondaryMuscles":[],"category":"forca","instructions":["Deite-se em um banco plano segurando dois halteres diretamente acima dos ombros, com os braços totalmente estendidos e formando um ângulo de 90 graus com o torso.","As palmas das mãos devem estar voltadas para frente e os cotovelos próximos ao corpo. Esta é sua posição inicial.","Inspire e abaixe os halteres lentamente até próximo às orelhas, mantendo a parte superior dos braços imóvel.","Expire e use o tríceps para retornar os pesos à posição inicial."],"tracking":"weight_reps"},{"id":"Decline_Close-Grip_Bench_To_Skull_Crusher","name":"Supino Declinado com Pegada Fechada e Tríceps Testa","force":"push","level":"intermediario","mechanic":"composto","equipment":"barra","primaryMuscles":["triceps"],"secondaryMuscles":["peito","ombros"],"category":"forca","instructions":["Prenda as pernas na extremidade do banco declinado e deite-se lentamente.","Com uma pegada fechada (ligeiramente mais estreita que a largura dos ombros), levante a barra do rack e segure-a acima de você com os braços travados e cotovelos para dentro, perpendiculares ao chão. Esta é a posição inicial. Dica: Peça ajuda para retirar a barra.","Desça a barra em direção ao peito inferior, inspirando e mantendo os cotovelos próximos ao corpo.","Use o tríceps para empurrar a barra de volta à posição inicial, expirando."],"tracking":"weight_reps"}];
